class FakeDecoderLLM:
    def _stream_chat_http(self, *args, **kwargs):
        return '{"decoded_terms":[],"needs_verification":false,"overall_confidence":"none","notes":"ok"}'


class FakeMultimodalLLM:
    backend = "http"
    server_type = "vllm"

    def __init__(self) -> None:
        self.calls = []

    def complete_multimodal_json(self, _system_prompt, _user_text, images, **_kwargs):
        urls = [str((img or {}).get("source_url") or "") for img in images]
        self.calls.append(urls)
        payload_images = []
        for idx, url in enumerate(urls):
            payload_images.append(
                {
                    "source_url": url,
                    "ocr_text": f"OCR {idx + 1}",
                    "visual_summary": f"요약 {idx + 1}",
                    "explicit_work_title": f"작품{idx + 1}",
                    "explicit_author_name": "작가A",
                    "work_cues": [f"단서{idx + 1}"],
                    "confidence": "High",
                    "evidence_type": "explicit_text",
                }
            )
        return {"images": payload_images, "chunk_summary": "청크 요약", "limitations": []}


