def _build_pipeline() -> AgenticPipeline:
    return AgenticPipeline(llm=DummyLLM(), mcp=DummyMCP(), max_iterations=2)


class AgenticPipelineReworkTest(unittest.TestCase):
    def test_correct_title_final_fast_paths_verifier_official_lock(self):
        pipeline = _build_pipeline()
        ctx = ConversationContext(
            post_id=11702087,
            post_data={
                "post_id": 11702087,
                "title": "괴담 호텔 탈출기 설정 질문",
                "content_blocks": [{"type": "text", "text": "아리 유산이 뭐임"}],
            },
            comments=[],
        )
        ctx.set_expert_output(
            ExpertType.VERIFIER,
            {
                "verification_result": {
                    "novel_identity": {
                        "official_novel_title": "괴담 호텔 탈출기",
                        "heretic_url": "https://novelpia.com/novel/102155",
                        "confidence": "High",
                    },
                    "grounding_check": {"anchor_found": "character_mention"},
                },
                "final_confidence": "high",
            },
        )

        def _raise_source_quality(*_args, **_kwargs):
            raise AssertionError("source-quality scoring should be skipped")

        pipeline._collect_title_source_quality = _raise_source_quality

        corrected = pipeline._correct_title_final("괴담 호텔 탈출기", ctx)

        self.assertEqual(corrected, "괴담 호텔 탈출기")

    def test_correct_title_final_blocks_verifier_lock_when_relation_rejects(self):
        pipeline = _build_pipeline()
        ctx = ConversationContext(
            post_id=11700470,
            post_data={
                "post_id": 11700470,
                "title": "어케 주인공 죄목이",
                "content_blocks": [
                    {
                        "type": "text",
                        "text": "B급 모험가 밤도깨비 에이브가 되어 있었다.",
                    }
                ],
            },
            comments=[],
        )
        ctx.set_expert_output(
            ExpertType.VERIFIER,
            {
                "verification_result": {
                    "novel_identity": {
                        "official_novel_title": "도깨비 덕분에 슈퍼스타",
                        "heretic_url": "https://series.naver.com/novel/detail.series?productNo=5645331",
                        "confidence": "High",
                    },
                    "grounding_check": {"anchor_found": "character_mention"},
                    "relation_judgment": {
                        "relation_type": "thematic_overlap_only",
                        "discussion_target": "mixed_or_uncertain",
                        "promotion_decision": "reject",
                    },
                    "counter_arguments": [
                        {
                            "severity": "critical",
                            "issue": "relation_judge:thematic_overlap_only",
                        }
                    ],
                },
                "final_confidence": "high",
            },
        )

        def _raise_source_quality(*_args, **_kwargs):
            raise AssertionError("source-quality scoring should be skipped")

        pipeline._collect_title_source_quality = _raise_source_quality

        corrected = pipeline._correct_title_final("도깨비 덕분에 슈퍼스타", ctx)

        self.assertEqual(corrected, "")

    def test_fanfic_derivative_detail_without_direct_title_anchor_is_held(self):
        pipeline = _build_pipeline()
        title = "시스터즈가 되었다"
        ctx = ConversationContext(
            post_id=11663521,
            post_data={
                "post_id": 11663521,
                "title": "TS) 시스터즈 퍼스트 정신머리 고치려면",
                "content_blocks": [
                    {"type": "text", "text": "고쳐질때까지 토우마가 갱생펀치 갈기면 되지 않을까?"}
                ],
            },
            comments=[],
        )
        ctx.search_results = [
            {
                "title": "웹소설로 꿈꾸는 세상! - [초전자포] 시스터즈가 되었다 - 노벨피아",
                "url": "https://novelpia.com/novel/357856",
                "content": "자유 [초전자포] 시스터즈가 되었다 #패러디 #어과초 #어마금 #초전자포 #TS",
            },
            {
                "title": "어떤 마술의 금서목록/비판 - 나무위키",
                "url": "https://namu.wiki/w/어떤%20마술의%20금서목록",
                "content": "카미조 토우마와 갱생펀치 관련 비판 문서.",
            },
        ]

        result = pipeline._apply_output_consistency_validator(
            ctx=ctx,
            is_relevant=True,
            discussion_type="character_talk",
            official_title=title,
            confidence="High",
            reason="검색 결과의 패러디 작품으로 판정",
            notes=None,
            title_candidates=[
                DetectedTitle(
                    official_title=title,
                    heretic_url="https://novelpia.com/novel/357856",
                    confidence="High",
                    source_tier="official_detail",
                )
            ],
            primary_work=DetectedTitle(
                official_title=title,
                heretic_url="https://novelpia.com/novel/357856",
                confidence="High",
                source_tier="official_detail",
            ),
            mentioned_works=[],
            comparison_target=None,
            recommendation_candidates=[],
            metadata={},
            verification_result={"grounding_check": {"anchor_found": "character_mention"}},
        )

        self.assertTrue(result["is_relevant"], result)
        self.assertIsNone(result["official_title"])
        self.assertEqual(result["work_resolution"], "unresolved")
        self.assertIn("fanfic_derivative_title_unanchored_hold", result["consistency_flags"])

    def test_correct_title_final_keeps_current_alias_before_acknowledged_previous_work(self):
        pipeline = _build_pipeline()
        ctx = ConversationContext(
            post_id=11713222,
            post_data={
                "post_id": 11713222,
                "title": "현대 하렘물은 진짜 잘쓰는 작가가 손에꼽네",
                "content_blocks": [
                    {
                        "type": "text",
                        "text": "잘생인방보는데 그냥 주인공이 여자를 오나홀로밖에 안보는거같음",
                    }
                ],
            },
            comments=[
                "전작도 잘생인편으로 현대하렘아님?",
                "그렇네 잘생인편 안봐서 까먹어버림",
            ],
        )
        ctx.search_results = [
            {
                "title": "잘생기면 편해지는 인방 생활",
                "url": "https://novelpia.com/novel/384016",
                "content": "노벨피아 작품 잘생기면 편해지는 인방 생활",
            },
            {
                "title": "잘생기면 인생이 편하다",
                "url": "https://novelpia.com/novel/300042",
                "content": "노벨피아 작품 잘생기면 인생이 편하다",
            },
        ]
        ctx.set_expert_output(
            ExpertType.VERIFIER,
            {
                "verification_result": {
                    "novel_identity": {
                        "official_novel_title": "잘생기면 편해지는 인방 생활",
                        "heretic_url": "https://novelpia.com/novel/384016",
                        "confidence": "High",
                        "evidence_type": "search_platform_url",
                    },
                    "grounding_check": {
                        "anchor_found": "title_mention",
                        "matched_alias": "잘생인방",
                        "body_abbrev_mentioned": True,
                    },
                    "relation_judgment": {
                        "relation_type": "explicit_alias",
                        "discussion_target": "specific_work",
                        "promotion_decision": "allow",
                        "observed_aliases": ["잘생인방"],
                        "search_support_summary": {
                            "alias_in_post_count": 1,
                            "explicit_alias_bridge_count": 1,
                            "best_official_url": "https://novelpia.com/novel/384016",
                        },
                    },
                    "slang_insight": {
                        "detected_term": "잘생인방",
                        "decoded_term": "잘생기면 편해지는 인방 생활",
                        "decode_verified": True,
                        "canonical_work_alias": "잘생인방",
                    },
                },
                "final_confidence": "high",
            },
        )
        ctx.set_expert_output(
            ExpertType.SYNTHESIZER,
            {
                "hidden_references": [
                    {
                        "reference_type": "alias",
                        "surface": "잘생인방",
                        "matched_to": "잘생기면 편해지는 인방 생활",
                    }
                ]
            },
        )

        corrected = pipeline._correct_title_final("잘생기면 편해지는 인방 생활", ctx)

        self.assertEqual(corrected, "잘생기면 편해지는 인방 생활")
        self.assertFalse(hasattr(ctx, "_acknowledged_previous_work_comment_override_title"))
        preserved = getattr(ctx, "_acknowledged_previous_work_comment_preservation_candidate", {})
        self.assertEqual(preserved.get("official_title"), "잘생기면 인생이 편하다")
        self.assertEqual(preserved.get("heretic_url"), "https://novelpia.com/novel/300042")
        self.assertEqual(preserved.get("alias_or_mention"), "잘생인편")

    def test_correct_title_final_sets_acknowledged_previous_work_lock_for_same_title(self):
        pipeline = _build_pipeline()
        ctx = ConversationContext(
            post_id=11713222,
            post_data={
                "post_id": 11713222,
                "title": "현대 하렘물은 진짜 잘쓰는 작가가 손에꼽네",
                "content_blocks": [
                    {
                        "type": "text",
                        "text": "잘생인방보는데 그냥 주인공이 여자를 오나홀로밖에 안보는거같음",
                    }
                ],
            },
            comments=[
                "판타지만 쓰던 작가라서 그런가",
                "전작도 잘생인편으로 현대하렘아님?",
                "@ㅇㅇ\n그렇네 잘생인편 안봐서 까먹어버림",
            ],
        )
        ctx.search_results = [
            {
                "title": "웹소설로 꿈꾸는 세상! - 잘생기면 인생이 편하다 - 노벨피아",
                "url": "https://novelpia.com/novel/300042",
                "content": "플러스작품 - 잘생기면 인생이 편하다. 잘생긴 김에, 배우 해야겠다.",
                "purpose": "title_body_sanitized_platform_probe",
            }
        ]
        ctx.set_expert_output(
            ExpertType.VERIFIER,
            {
                "verification_result": {
                    "novel_identity": {
                        "official_novel_title": "잘생기면 인생이 편하다",
                        "heretic_url": "https://novelpia.com/novel/300042",
                        "confidence": "High",
                        "evidence_type": "search_platform_url",
                    },
                    "grounding_check": {
                        "anchor_found": "title_mention",
                        "matched_alias": "잘생인방",
                    },
                },
                "final_confidence": "high",
            },
        )

        corrected = pipeline._correct_title_final("잘생기면 인생이 편하다", ctx)

        self.assertEqual(corrected, "잘생기면 인생이 편하다")
        self.assertEqual(
            getattr(ctx, "_acknowledged_previous_work_comment_override_title", ""),
            "잘생기면 인생이 편하다",
        )
        self.assertEqual(
            getattr(ctx, "_acknowledged_previous_work_comment_override_url", ""),
            "https://novelpia.com/novel/300042",
        )
        self.assertEqual(
            getattr(ctx, "_acknowledged_previous_work_comment_override_alias", ""),
            "잘생인편",
        )

