    def test_semantic_seed_positive_keep_query_is_not_specific_work_denied(self):
        fake_llm = FakeSemanticSeedReviewLLM(
            """
            {
              "post_intent": "특정 작품 약칭으로 결말 반응을 말한다.",
              "content_interpretation": "제목 표면어는 단독 확정은 어렵지만 작품 약칭 후보로 검색 검증할 수 있다.",
              "is_specific_work_discussion": true,
              "recommended_intent": "express_opinion",
              "recommended_target_kind": "work",
              "title_seed_reviews": [
                {"surface": "작약별", "decision": "context_only", "confidence": "medium", "reason": "단독 공식명 확정은 아님"}
              ],
              "search_query_reviews": [
                {"query": "작약별 결말", "decision": "keep", "confidence": "medium", "reason": "약칭 후보와 결말 반응을 같이 검증"}
              ],
              "warnings": []
            }
            """
        )
        discourse = DiscourseAnalyzer(fake_llm)
        post_json = {
            "post_id": 910003,
            "title": "작약별 결말이 왜이러냐",
            "content": ["장르 전개 뭐다이"],
            "comments": [],
        }

        sanitized = discourse._sanitize_result(
            {
                "discourse_analysis": {
                    "primary_domain": "novel_literature",
                    "intent": "discuss_work",
                    "speech_act": "review",
                    "target_kind": "work",
                    "title_novel_terms": ["작약별"],
                    "search_suggestions": [
                        {"query": "작약별 결말", "purpose": "title_search", "priority": 1}
                    ],
                }
            },
            post_json=post_json,
        )

        da = sanitized["discourse_analysis"]
        self.assertTrue(da["semantic_seed_review"]["is_specific_work_discussion"])
        self.assertEqual(da["search_suggestions"][0]["query"], "작약별 결말")
        self.assertIn("semantic_seed_review_non_title_terms_removed", da["warnings"])
        self.assertNotIn("semantic_seed_review_specific_work_denied", da["warnings"])
        self.assertNotIn("semantic_seed_review_search_suggestions_removed", da["warnings"])

        ctx = ConversationContext(post_id=910003, post_data=post_json, comments=[])
        ctx.set_expert_output(ExpertType.DISCOURSE, sanitized)
        orchestrator = Orchestrator(experts={})
        self.assertFalse(orchestrator._has_discourse_semantic_seed_demotion(ctx))
        allowed, reason = orchestrator._title_search_intent_permit(ctx)
        self.assertTrue(allowed)
        self.assertEqual(reason, "")

