    def test_relation_hold_keeps_structural_official_recall_resolution(self):
        pipeline = _build_pipeline()
        title = "[림월드]변방계에서 회귀자로 살아남기"
        post_json = {
            "post_id": 11698897,
            "title": "랫따싶 림월드 요소 생각나게 하는거 좋네에",
            "content_blocks": [
                {
                    "type": "text",
                    "text": "림월드 변방계 최대의 적폐 건물 같은 장면이 좋았음. #패러디 #림월드 #랫따싶",
                }
            ],
        }
        ctx = ConversationContext(post_id=11698897, post_data=post_json, comments=[])
        ctx.primary_domain = "novel_literature"
        ctx.set_expert_output(
            ExpertType.GATEKEEPER,
            {
                "context_clues": {
                    "title_as_body_continuation": True,
                    "title_body_joined_text": (
                        "랫따싶 림월드 요소 생각나게 하는거 좋네에 "
                        "림월드 변방계 최대의 적폐 건물 같은 장면이 좋았음. #패러디 #림월드 #랫따싶"
                    ),
                }
            },
        )
        ctx.set_expert_output(
            ExpertType.DISCOURSE,
            {
                "discourse_analysis": {
                    "primary_domain": "novel_literature",
                    "intent": "discuss_work",
                    "target_kind": "work",
                }
            },
        )
        ctx.search_results = [
            {
                "title": f"웹소설로 꿈꾸는 세상! - {title} - 노벨피아",
                "url": "https://novelpia.com/novel/382324",
                "content": "잡탕 종족모드가 적용된 변방계에 떨어졌다. #패러디 #림월드 #랫따싶.",
                "from_query": "랫따싶 노벨피아",
                "purpose": "title_alias_platform_recall",
            }
        ]
        verification = {
            "is_relevant": True,
            "is_novel_discussion": True,
            "grounding_check": {
                "anchor_found": "title_abbrev_mention",
                "matched_alias": "랫따싶",
            },
            "relation_judgment": {
                "relation_type": "explicit_alias",
                "discussion_target": "specific_work",
                "promotion_decision": "hold",
                "post_direct_grounding": False,
                "reason": "약칭 기반 역검색이라 relation judge는 hold",
            },
        }

        self.assertTrue(
            pipeline._relation_hold_should_block_title_resolution(
                ctx=ctx,
                official_title=title,
                verification_result=verification,
            )
        )
        self.assertTrue(
            pipeline._should_keep_final_semantic_resolution_after_official_recall_anchor(
                ctx=ctx,
                official_title=title,
                verification_result=verification,
                title_candidates=[
                    DetectedTitle(
                        official_title=title,
                        heretic_url="https://novelpia.com/novel/382324",
                        confidence="High",
                        source_tier="official_detail",
                        page_type="novel_page",
                        alias_or_mention="림월드 랫따싶",
                    )
                ],
                consistency_flags=[
                    "official_url_recall_gate_recovered",
                    "title_body_search_result:림월드 랫따싶",
                    "title_body_official_detail_anchor",
                ],
            )
        )
        self.assertFalse(
            pipeline._should_keep_final_semantic_resolution_after_official_recall_anchor(
                ctx=ctx,
                official_title=title,
                verification_result=verification,
                title_candidates=[
                    DetectedTitle(
                        official_title=title,
                        heretic_url="https://novelpia.com/novel/382324",
                        confidence="High",
                        source_tier="official_detail",
                        page_type="novel_page",
                        alias_or_mention="림월드 랫따싶",
                    )
                ],
                consistency_flags=[
                    "official_url_recall_gate_recovered",
                    "title_body_search_result:림월드 랫따싶",
                    "title_body_official_detail_anchor",
                    "recommendation_context_only_no_work_anchor",
                ],
            )
        )

        blocked_fields = pipeline._derive_resolution_scope_fields(
            ctx=ctx,
            is_relevant=True,
            official_title=title,
            discussion_type="general",
            topicality="core_relevant",
            subtype="resolved_work",
            work_resolution="resolved",
            verification_result=verification,
            final_decision={},
        )
        guarded_fields = pipeline._derive_resolution_scope_fields(
            ctx=ctx,
            is_relevant=True,
            official_title=title,
            discussion_type="general",
            topicality="core_relevant",
            subtype="resolved_work",
            work_resolution="resolved",
            verification_result=verification,
            final_decision={
                "consistency_flags": ["relation_hold_official_recall_guarded_resolution"],
            },
        )

        self.assertEqual(blocked_fields["title_resolution_state"], "unresolved_matchable")
        self.assertFalse(blocked_fields["title_resolution_allowed"])
        self.assertEqual(guarded_fields["title_resolution_state"], "resolved")
        self.assertTrue(guarded_fields["title_resolution_allowed"])

    def test_known_abbreviation_wrapped_title_expands_search_seed(self):
        orchestrator = Orchestrator(experts={})
