    def test_session_knowledge_does_not_promote_image_author_surface_as_slang(self):
        pipeline = _build_pipeline()
        title = "아카데미의 피해자"
        ctx = ConversationContext(
            post_id=11718117,
            post_data={
                "post_id": 11718117,
                "title": "싸우던 중에 갑자기 만담 뭐냐 ㅋㅋㅋ",
                "image_enrichment": [
                    {
                        "promotion_eligible": True,
                        "explicit_work_title": title,
                        "explicit_author_name": "양파랑",
                        "evidence_type": "explicit_text",
                        "title_role": "work_title",
                        "ocr_text": "아카데미의 피해자 양파랑 | 268 테세우스의 배 (6) 중 KAKAOPAGE",
                    }
                ],
            },
            comments=[],
        )
        ctx.set_expert_output(
            ExpertType.DECODER,
            {
                "decoded_terms": [
                    {
                        "original": "양파랑",
                        "is_author_name": True,
                        "author_info": {"author_name": "양파랑"},
                        "best_match": {"title": title},
                    }
                ]
            },
        )
        ctx.set_expert_output(
            ExpertType.GATEKEEPER,
            {"detected_entities": {"possible_authors": ["양파랑"]}},
        )
        ctx.set_expert_output(
            ExpertType.VERIFIER,
            {
                "verification_result": {
                    "novel_identity": {
                        "official_title": title,
                        "heretic_url": "https://page.kakao.com/content/66611775",
                        "confidence": "High",
                    },
                    "grounding_check": {
                        "anchor_found": "plot_mention",
                        "decoder_grounded": True,
                    },
                    "author_info": {"detected_author": "양파랑"},
                }
            },
        )
        result = PickvelOutputItemV2(
            post_id=11718117,
            identity=PickvelIdentity(
                is_relevant=True,
                novel_identity=NovelIdentity(
                    official_title=title,
                    heretic_url="https://page.kakao.com/content/66611775",
                    confidence="High",
                ),
                discussion_type="character_talk",
            ),
        )

        with patch.object(
            pipeline,
            "_compute_title_commitment",
            return_value={
                "score": 15,
                "official_evidence": True,
                "title_in_context": True,
                "bucket_score": 5,
            },
        ), patch.object(pipeline, "_is_title_commitment_medium", return_value=True), patch.object(
            pipeline,
            "_is_title_commitment_strong",
            return_value=True,
        ), patch.object(pipeline, "_has_official_title_evidence", return_value=True), patch.object(
            pipeline,
            "_title_mentioned_in_post_main_context",
            return_value=True,
        ):
            pipeline._update_session_knowledge(ctx, result)

        author_key = pipeline._normalize_author_candidate("양파랑")
        slang_key = pipeline._normalize_match_text("양파랑")
        self.assertNotIn(slang_key, pipeline.session_knowledge["resolved_slang"])
        self.assertNotIn(slang_key, pipeline.session_knowledge["pending_slang"])
        self.assertEqual(pipeline.session_knowledge["resolved_authors"][author_key], title)

