    def test_exact_slang_alias_blocks_sentiment_wrapped_surface_rescue(self):
        pipeline = _build_pipeline()
        memory = BatchContextMemory(enabled=True)
        memory.register_abbreviation(
            "히집악",
            "히어로가 집착하는 악당이 되었다",
            confidence=3,
            fast_promote=True,
        )
        pipeline.batch_context = memory
        pipeline._has_family_alias_ambiguity = lambda *args, **kwargs: True
        ctx = ConversationContext(
            post_id=11205204,
            post_data={
                "post_id": 11205204,
                "title": "아 히집악 너무 좋아",
                "content_blocks": [{"type": "text", "text": "사랑해"}],
            },
            comments=[],
        )
        ctx.set_expert_output(
            ExpertType.DISCOURSE,
            {"discourse_analysis": {"title_novel_terms": ["히집악"]}},
        )
        wrong_surface = DetectedTitle(
            official_title="위장 취업한 나에게 그녀들이 집착한다",
            heretic_url="https://novelpia.com/novel/220309",
            confidence="High",
            alias_or_mention="아 히집악 너무 좋아",
            source_tier="official_detail",
            page_type="novel_page",
            content_status="active",
        )

        forms = pipeline._candidate_title_surface_forms_in_post_title(ctx, wrong_surface)
        candidate, hit = pipeline._resolve_batch_memory_alias_candidate(ctx)

        self.assertEqual(forms, [])
        self.assertIsNotNone(candidate)
        self.assertIsNotNone(hit)
        self.assertEqual(candidate.official_title, "히어로가 집착하는 악당이 되었다")
        self.assertEqual(hit["alias"], "히집악")

    def test_batch_alias_canonical_base_corrects_episode_variant_title(self):
        pipeline = _build_pipeline()
        memory = BatchContextMemory(enabled=True)
        memory.register_abbreviation(
            "빌환",
            "빌어먹을 환생",
            confidence=3,
            fast_promote=True,
        )
        pipeline.batch_context = memory
        ctx = ConversationContext(
            post_id=11718099,
            post_data={
                "post_id": 11718099,
                "title": "빌환 표지변경됨",
                "content_blocks": [{"type": "text", "text": "시엘이랑 세냐 언급"}],
            },
            comments=[],
        )
        ctx.set_expert_output(
            ExpertType.ARBITER,
            {
                "final_decision": {
                    "is_relevant": True,
                    "official_novel_title": "빌어먹을 환생 2화",
                    "official_title": "빌어먹을 환생 2화",
                    "heretic_url": "https://novel.munpia.com/222360",
                    "confidence": "High",
                    "discussion_type": "character_talk",
                },
                "metadata_synthesis": {},
            },
        )
        ctx.set_expert_output(
            ExpertType.VERIFIER,
            {
                "verification_result": {
                    "is_relevant": True,
                    "novel_identity": {
                        "official_title": "빌어먹을 환생 2화",
                        "official_novel_title": "빌어먹을 환생 2화",
                        "heretic_url": "https://novel.munpia.com/222360",
                        "confidence": "High",
                    },
                    "grounding_check": {"anchor_found": "plot_mention"},
                }
            },
        )

        old_validator = pipeline._apply_output_consistency_validator
        pipeline._apply_output_consistency_validator = lambda **_kwargs: {
            "is_relevant": True,
            "discussion_type": "character_talk",
            "topicality": "core_relevant",
            "subtype": "resolved_work",
            "work_resolution": "resolved",
            "anchor_type": "title_exact",
            "anchor_strength": "high",
            "context_sources": ["title", "body", "search"],
            "consistency_flags": [],
            "primary_subject_type": None,
            "primary_subject_text": None,
            "secondary_reference_works": [],
            "reason": "episode variant candidate",
            "notes": "episode variant candidate",
            "confidence": "High",
            "official_title": "빌어먹을 환생 2화",
            "heretic_url": "https://novel.munpia.com/222360",
        }
        try:
            result = pipeline._context_to_output(ctx)
        finally:
            pipeline._apply_output_consistency_validator = old_validator

        identity = result.identity
        self.assertTrue(identity.is_relevant)
        self.assertIsNotNone(identity.novel_identity)
        self.assertEqual(identity.novel_identity.official_title, "빌어먹을 환생")
        self.assertIn("batch_memory_alias_canonical_base_corrected", identity.consistency_flags or [])

