    def test_direct_full_title_rescue_clears_stale_demotions(self):
        pipeline = _build_pipeline()
        title = "\ub9dd\ud55c \uad50\ub2e8\uc758 \uc131\uae30\uc0ac"
        ctx = ConversationContext(
            post_id=10190186,
            post_data={
                "post_id": 10190186,
                "title": f"(\uc54c\ub9bc) {title} \ub2e4\uc74c\uc8fc\uc5d0 \uc720\ub8cc\ud654\ub428",
                "content_blocks": [{"type": "text", "text": "3\uc77c\ub0a8\uc558\uc73c\ub2c8\uae4c \ubcf4\ub7ec\uac00\uc790"}],
            },
            comments=[],
        )
        ctx.search_results = [
            {
                "title": f"{title} - \ubb38\ud53c\uc544",
                "url": "https://m.munpia.com/novel/detail/457750",
                "content": f"{title} \uc720\ub8cc\ud654 \uc548\ub0b4",
            }
        ]
        ctx.set_expert_output(
            ExpertType.ARBITER,
            {"final_decision": {"is_relevant": True, "confidence": "Low"}, "metadata_synthesis": {}},
        )
        ctx.set_expert_output(
            ExpertType.VERIFIER,
            {"verification_result": {"novel_identity": {}, "grounding_check": {"anchor_found": "plot_mention"}}},
        )

        old_validator = pipeline._apply_output_consistency_validator
        old_picker = pipeline._pick_direct_full_title_candidate_for_hold
        old_signal = pipeline._has_title_led_work_announcement_signal
        pipeline._apply_output_consistency_validator = lambda **_kwargs: {
            "is_relevant": True,
            "discussion_type": "noise",
            "topicality": "core_relevant",
            "subtype": "unresolved_work",
            "work_resolution": "unresolved",
            "anchor_type": "none",
            "anchor_strength": "low",
            "context_sources": ["title", "body", "search"],
            "consistency_flags": [
                "family_alias_group_unresolved",
                "external_ip_unresolved_final_blocked",
                "primary_work_cleared_non_core",
                "notes_demoted_for_unresolved",
            ],
            "primary_subject_type": None,
            "primary_subject_text": None,
            "secondary_reference_works": [],
            "reason": "stale unresolved hold",
            "notes": "stale unresolved hold",
            "confidence": "Low",
            "official_title": None,
        }
        pipeline._pick_direct_full_title_candidate_for_hold = lambda **_kwargs: DetectedTitle(
            official_title=title,
            heretic_url="https://m.munpia.com/novel/detail/457750",
            confidence="High",
            source_tier="official_detail",
        )
        pipeline._has_title_led_work_announcement_signal = lambda _ctx: True

        try:
            result = pipeline._context_to_output(ctx)
        finally:
            pipeline._apply_output_consistency_validator = old_validator
            pipeline._pick_direct_full_title_candidate_for_hold = old_picker
            pipeline._has_title_led_work_announcement_signal = old_signal

        identity = result.identity
        self.assertTrue(identity.is_relevant)
        self.assertIsNotNone(identity.novel_identity)
        self.assertEqual(identity.novel_identity.official_title, title)
        self.assertEqual(identity.novel_identity.confidence, "High")
        self.assertEqual(identity.discussion_type, "general")
        self.assertEqual(identity.work_resolution, "resolved")
        self.assertEqual(identity.subtype, "resolved_work")
        self.assertEqual(identity.anchor_type, "title_exact")
        flags = set(identity.consistency_flags or [])
        self.assertIn("direct_full_title_candidate_rescued", flags)
        self.assertIn("direct_full_title_rescue_cleared_stale_demotions", flags)
        self.assertNotIn("family_alias_group_unresolved", flags)
        self.assertNotIn("external_ip_unresolved_final_blocked", flags)
        self.assertNotIn("primary_work_cleared_non_core", flags)
        self.assertNotIn("notes_demoted_for_unresolved", flags)
        verification = ctx.get_expert_output(ExpertType.VERIFIER)["verification_result"]
        self.assertEqual(verification["novel_identity"]["official_title"], title)
        self.assertEqual(verification["novel_identity"]["confidence"], "High")

