        self.assertIn("stable_batch_alias_conflict_corrected", flags)
        self.assertIn("search_title_conflict_with_stable_alias", flags)
        # 검색 회수 URL과 정확한 공식 표시 제목에 결속된 공개 URL은 별도이다.
        decision = identity.promotion_decision or {}
