    def test_batch_memory_exact_alias_rescue_recovers_official_url(self):
        pipeline = _build_pipeline()
        # 검색 후보만 제공한다. 기존 디스크 캐시가 공식 pair를 대신하지 못하게 한다.
        pipeline.enable_url_fetch_disk_cache = False
        pipeline.mcp.fetch = lambda _url: None
        stable_candidate = DetectedTitle(
            official_title="빌어먹을 환생",
            heretic_url=None,
            confidence="High",
            alias_or_mention="빌환",
            source_tier="mixed",
            page_type=None,
            locked=True,
        )
        hit = {
            "alias": "빌환",
            "title": "빌어먹을 환생",
            "confidence": 3,
            "source": "batch_memory",
        }
        ctx = ConversationContext(
            post_id=11718099,
            post_data={
                "post_id": 11718099,
                "title": "빌환 표지변경됨",
                "content_blocks": [{"type": "text", "text": "시엘이랑 세냐 빼고 매르만 있어도 된다는 말은 ㄴㄴ"}],
            },
            comments=[],
        )

        old_validator = pipeline._apply_output_consistency_validator
        old_freeze = pipeline._freeze_identity_references
        old_selector = pipeline._select_single_locked_official_candidate
        old_signal = pipeline._has_title_led_work_announcement_signal
        old_batch = pipeline._resolve_batch_memory_alias_candidate
        old_block = pipeline._weak_rescue_rejection_profile
        old_search = pipeline._search_with_meta
        old_validate_url = pipeline._validate_heretic_url
        pipeline._apply_output_consistency_validator = lambda **_kwargs: {
            "is_relevant": False,
            "discussion_type": "noise",
            "topicality": "unrelated",
            "subtype": "other_quarantine",
            "work_resolution": "none",
            "anchor_type": "none",
            "anchor_strength": "low",
            "context_sources": ["title", "body", "search"],
            "consistency_flags": ["notes_demoted_for_unresolved"],
            "reason": "표지변경을 작품명처럼 보아 보류됨.",
            "notes": "표지변경을 작품명처럼 보아 보류됨.",
            "confidence": "Low",
            "official_title": None,
        }
        pipeline._freeze_identity_references = lambda **_kwargs: {
            "official_title": None,
            "heretic_url": None,
            "primary_work": None,
            "future_watch_target": None,
            "title_candidates": [],
            "mentioned_works": [],
            "comparison_target": None,
            "recommendation_candidates": [],
            "consistency_flags": ["notes_demoted_for_unresolved"],
        }
        pipeline._select_single_locked_official_candidate = lambda **_kwargs: None
        pipeline._has_title_led_work_announcement_signal = lambda _ctx: False
        pipeline._resolve_batch_memory_alias_candidate = lambda *_args, **_kwargs: (stable_candidate, hit)
        pipeline._weak_rescue_rejection_profile = lambda **_kwargs: {"reject": False}
        pipeline._search_with_meta = lambda query, purpose="": (
            [
                {
                    "title": "빌어먹을 환생 - 문피아 웹소설 - Munpia",
                    "url": "https://novel.munpia.com/222360",
                    "content": "빌어먹을 환생. 목마 - 동료였던 용사의 후손으로 환생했다.",
                }
            ],
            {"degraded": False},
        ) if "빌어먹을 환생" in str(query) else ([], {"degraded": False})
        pipeline._validate_heretic_url = lambda url, _ctx, identified_title=None: None

        try:
            result = pipeline._context_to_output(ctx)
        finally:
            pipeline._apply_output_consistency_validator = old_validator
            pipeline._freeze_identity_references = old_freeze
            pipeline._select_single_locked_official_candidate = old_selector
            pipeline._has_title_led_work_announcement_signal = old_signal
            pipeline._resolve_batch_memory_alias_candidate = old_batch
            pipeline._weak_rescue_rejection_profile = old_block
            pipeline._search_with_meta = old_search
            pipeline._validate_heretic_url = old_validate_url

        identity = result.identity
        import json
        inventory_diagnostic = json.dumps({
            "case": "r6_rework_07_candidate_url", "identity": identity.model_dump(mode="json")},
            ensure_ascii=False, sort_keys=True)
        print("[r6_rework_inventory] " + inventory_diagnostic, file=sys.stderr)
        self.assertTrue(identity.is_relevant)
        self.assertIsNotNone(identity.novel_identity)
        self.assertEqual(identity.novel_identity.official_title, "빌어먹을 환생")
        self.assertIsNone(identity.novel_identity.heretic_url)
        flags = set(identity.consistency_flags or [])
        self.assertIn("batch_memory_exact_alias_rescued", flags)
        decision = identity.promotion_decision or {}
        self.assertIsNone(decision.get("official_url"))
        self.assertIn("official_url_evidence_missing", decision.get("reason_codes") or [])
        self.assertIn("official_detail_display_binding_unavailable", decision.get("reason_codes") or [])
        ledger = identity.candidate_ledger or {}
        # 제목 공개와 URL 보류를 거친 실제 보존 snapshot을 관측한다.
        retained = identity.candidate_preservation_sources or []
        self.assertEqual((ledger.get("candidate_generation") or {}).get("emitted_source_count"),
            len(retained), inventory_diagnostic)
        self.assertTrue(any(item.get("official_title") == "빌어먹을 환생"
            and item.get("heretic_url") == "https://novel.munpia.com/222360"
            for item in retained), inventory_diagnostic)
        pair_evidence = [item for item in (identity.promotion_gate_evidence or [])
            if item.get("candidate_url") == "https://novel.munpia.com/222360"]
        self.assertTrue(pair_evidence)
        self.assertFalse(any(item.get("supports_publish") is True for item in pair_evidence))

