    def test_title_matched_official_url_prefers_author_context_over_same_title_homonym(self):
        pipeline = _build_pipeline()
        title = "세상에 나쁜 영애는 없다"
        wrong_same_title_url = "https://novelpia.com/novel/233647"
        author_supported_url = "https://m.munpia.com/novel/detail/405699"
        related_series_url = "https://series.naver.com/novel/detail.series?productNo=11651797"
        ctx = ConversationContext(
            post_id=11703669,
            post_data={
                "post_id": 11703669,
                "title": "세나영 하렘 엔딩 아님?",
                "content_blocks": [{"type": "text", "text": "하렘엔딩 아닌 코리타에게 무슨 가치가 있음?"}],
            },
            comments=["세나영 웹툰화 됐고 코리타 외전 기다림"],
        )
        ctx.set_expert_output(
            ExpertType.GATEKEEPER,
            {"detected_entities": {"possible_authors": ["코리타"]}},
        )
        search_results = [
            {
                "rank": 1,
                "title": title,
                "url": wrong_same_title_url,
                "content": "빙의한 소설이 자꾸 멸망한다. 그래서 이번에는 마왕을 어릴 때부터 관리하기로 했다.",
            },
            {
                "rank": 2,
                "title": f"{title} - 문피아 웹소설",
                "url": author_supported_url,
                "content": "코리타 - 귀족 영애라는 족속들은 싸가지가 없거나, 머리에 꽃밭밖에 없다.",
            },
            {
                "rank": 3,
                "title": title,
                "url": related_series_url,
                "content": "귀족 영애라는 족속들은 싸가지가 없거나, 머리에 꽃밭밖에 없다.",
            },
        ]

        self.assertEqual(
            pipeline._get_identified_author(ctx),
            "코리타",
        )
        self.assertLess(
            pipeline._title_matched_official_url_quality(title, author_supported_url, search_results, ctx=ctx),
            pipeline._title_matched_official_url_quality(title, wrong_same_title_url, search_results, ctx=ctx),
        )
        self.assertEqual(
            pipeline._find_title_matched_official_url(title, search_results, ctx=ctx),
            author_supported_url,
        )

