    def test_kakao_comment_tab_webnovel_title_counts_as_sanitized_evidence(self):
        pipeline = _build_pipeline()
        title = "탐식의 재림"
        comment_url = "https://page.kakao.com/content/50219568?tab_type=comment"
        base_url = "https://page.kakao.com/content/50219568"
        ctx = ConversationContext(
            post_id=11705231,
            post_data={
                "post_id": 11705231,
                "title": "로유진은 레전드다",
                "content_blocks": [{"type": "text", "text": "설지후 백혜주 유선화"}],
            },
            comments=[],
        )
        ctx.search_results = [
            {
                "title": "탐식의 재림 - 웹소설 - 카카오페이지",
                "url": comment_url,
                "content": "로유진. 설지후. 추천탭 웹툰탭 웹소설탭 책탭 요일연재탭",
                "_purpose": "alias_bridge_search",
                "_query": "로유진 설지후",
            }
        ]

        self.assertFalse(pipeline._is_novel_detail_url(comment_url))
        self.assertEqual(
            pipeline._canonical_title_matched_kakao_non_detail_tab_url(ctx.search_results[0], title),
            base_url,
        )
        self.assertTrue(pipeline._has_clean_novel_detail_title_evidence(ctx, title))
        self.assertEqual(pipeline._find_title_matched_official_url(title, ctx.search_results, ctx=ctx), base_url)
        # catalog는 관측한 댓글 탭 URL을 보존하고, 정규화한 공식 URL과 구분한다.
        catalog = pipeline._build_search_evidence_catalog(ctx)
        self.assertEqual(catalog[0]["url"], comment_url)
        self.assertEqual(catalog[0]["source_tier"], "web")

