    def test_freeze_identity_repairs_kakao_comment_tab_url_to_official_detail(self):
        pipeline = _build_pipeline()
        title = "빌어먹을 환생"
        naver_url = "https://series.naver.com/novel/detail.series?productNo=5935188"
        comment_url = "https://page.kakao.com/content/56071101?tab_type=comment"
        ctx = ConversationContext(
            post_id=11718099,
            post_data={
                "post_id": 11718099,
                "title": "빌환 표지변경됨",
                "content_blocks": [{"type": "text", "text": "시엘이랑 세냐 빼고 아니스티나랑 매르"}],
            },
            comments=[],
        )
        ctx.search_results = [
            {
                "title": title,
                "url": comment_url,
                "content": "댓글 탭",
                "_purpose": "alias_bridge_search",
                "_query": "빌환 시엘 웹소설",
            },
            {
                "title": title,
                "url": naver_url,
                "content": "7화 시엘. 8화 시엘.",
                "_purpose": "alias_bridge_search",
                "_query": "빌환 시엘 웹소설",
            },
        ]
        primary = DetectedTitle(
            official_title=title,
            heretic_url=comment_url,
            confidence="High",
            alias_or_mention="빌환",
            source_tier="community",
            negative_evidence=["missing_official_url_for_official_detail"],
            locked=True,
        )
        candidate = DetectedTitle(
            official_title=title,
            heretic_url=None,
            confidence="High",
            alias_or_mention="빌환",
            source_tier="community",
            negative_evidence=["missing_official_url_for_official_detail"],
            locked=True,
        )

        frozen = pipeline._freeze_identity_references(
            ctx=ctx,
            is_relevant=True,
            official_title=title,
            heretic_url=comment_url,
            confidence="High",
            topicality="core_relevant",
            work_resolution="resolved",
            title_candidates=[candidate],
            primary_work=primary,
            mentioned_works=[],
            comparison_target=None,
            recommendation_candidates=[],
            future_watch_target=None,
            anchor_type="title_mention",
            consistency_flags=[],
        )

        self.assertEqual(frozen["heretic_url"], naver_url)
        self.assertEqual(frozen["primary_work"].heretic_url, naver_url)
        self.assertEqual(frozen["primary_work"].source_tier, "official_detail")
        self.assertEqual(frozen["primary_work"].page_type, "novel_page")
        self.assertIsNone(frozen["primary_work"].negative_evidence)
        self.assertEqual(frozen["title_candidates"][0].heretic_url, naver_url)
        self.assertEqual(frozen["title_candidates"][0].source_tier, "official_detail")
        self.assertIn("official_detail_url_repaired_from_search", frozen["consistency_flags"])

