    def test_context_to_output_direct_image_candidate_skips_stale_scan_but_respects_final_hold(self):
        pipeline = _build_pipeline()
        ocr_title = "여대생 가랑이 사이 무릎 꿇은 엄마들"
        ctx = ConversationContext(
            post_id=11716480,
            post_data={
                "post_id": 11716480,
                "title": "아오 포티햄",
                "content_blocks": [{"type": "image", "text": ""}],
                "image_enrichment": [
                    {
                        "ocr_text": f"{ocr_title} 작가명 후타보로 자유 연재 조회 335 추천 14 4회차",
                        "explicit_work_title": ocr_title,
                        "explicit_author_name": "후타보로",
                        "work_cues": [ocr_title, "조회 335", "추천 14", "4회차"],
                        "evidence_type": "explicit_text",
                        "title_role": "work_title",
                        "focus_role": "work_anchor",
                        "screen_type": "work_surface",
                        "surface_type": "official_detail_page",
                        "promotion_eligible": True,
                        "confidence": "High",
                    }
                ],
            },
            comments=["시밯"],
        )
        ctx.suspected_titles = [
            {
                "title": "여대생 (인터넷 방송인)",
                "confidence": "High",
                "source": "character_parenthetical",
            }
        ]
        ctx.discourse_warning = "non_novel(adult_content,high)"
        ctx.set_expert_output(
            ExpertType.GATEKEEPER,
            {
                "post_type": "work_discussion",
                "detected_entities": {"possible_titles": ["시밯", ocr_title, "후타보로"]},
            },
        )
        ctx.set_expert_output(
            ExpertType.DISCOURSE,
            {
                "discourse_analysis": {
                    "primary_domain": "adult_content",
                    "domain_confidence": "high",
                    "intent": "make_joke",
                    "target_kind": "work",
                }
            },
        )
        ctx.set_expert_output(
            ExpertType.VERIFIER,
            {
                "verification_result": {
                    "is_relevant": False,
                    "grounding_check": {"anchor_found": "title_mention"},
                }
            },
        )
        ctx.set_expert_output(
            ExpertType.ARBITER,
            {
                "final_decision": {
                    "is_relevant": False,
                    "is_novel_discussion": False,
                    "official_title": None,
                    "official_novel_title": None,
                    "heretic_url": None,
                    "confidence": "Medium",
                    "discussion_type": "noise",
                    "_title_deliberately_null": True,
                },
                "metadata_synthesis": {"detected_author": "후타보로"},
            },
        )

        def _raise_canonical_scan(**_kwargs):
            raise AssertionError("direct OCR work-surface lock should skip stale canonical rescue scan")

        captured = {}

        def _fake_validator(**kwargs):
            captured.update(kwargs)
            return {
                "is_relevant": kwargs["is_relevant"],
                "discussion_type": kwargs["discussion_type"],
                "topicality": "core_relevant",
                "subtype": "resolved_work",
                "work_resolution": "resolved",
                "anchor_type": "image",
                "anchor_strength": "high",
                "context_sources": ["image"],
                "consistency_flags": [],
                "primary_subject_type": None,
                "primary_subject_text": None,
                "secondary_reference_works": [],
                "reason": kwargs["reason"],
                "notes": kwargs["notes"],
                "confidence": kwargs["confidence"],
                "official_title": kwargs["official_title"],
                "heretic_url": None,
            }

        old_scan = pipeline._select_best_canonical_rescue_candidate
        old_validator = pipeline._apply_output_consistency_validator
        pipeline._select_best_canonical_rescue_candidate = _raise_canonical_scan
        pipeline._apply_output_consistency_validator = _fake_validator
        try:
            result = pipeline._context_to_output(ctx)
        finally:
            pipeline._select_best_canonical_rescue_candidate = old_scan
            pipeline._apply_output_consistency_validator = old_validator

        self.assertTrue(captured["is_relevant"])
        self.assertEqual(captured["official_title"], ocr_title)
        self.assertTrue(result.identity.is_relevant)
        # OCR 후보 전달은 보존해도 non_novel_media 최종 계약을 우회하지 않는다.
        self.assertIsNone(result.identity.novel_identity)
        self.assertIn(ocr_title, [candidate.official_title for candidate in result.identity.title_candidates or []])
        self.assertIn("direct_image_work_surface_lock", result.identity.consistency_flags or [])
        ledger = result.identity.candidate_ledger or {}
        decision = ledger.get("promotion_decision") or {}
        self.assertEqual(decision.get("status"), "candidate_only")
        self.assertIs(decision.get("publish_allowed"), False)
        self.assertIsNone(decision.get("official_title"))
        self.assertIsNone(decision.get("official_url"))
        self.assertFalse((ledger.get("promotion_decision") or {}).get("bypassed_gate"))
        self.assertEqual(result.identity.work_resolution, "unresolved")
        self.assertFalse(result.identity.title_resolution_allowed)

