    def test_title_matched_official_url_prefers_novel_detail_over_webtoon_media_hit(self):
        pipeline = _build_pipeline()
        title = "빌어먹을 환생"
        naver_url = "https://series.naver.com/novel/detail.series?productNo=5935188"
        kakao_webtoon_url = "https://page.kakao.com/content/59617058"
        search_results = [
            {
                "rank": 1,
                "title": "빌어먹을 환생 - 웹툰 | 카카오페이지",
                "url": kakao_webtoon_url,
                "content": "웹툰 연재 작품. 원작 소설 기반 웹툰.",
            },
            {
                "rank": 2,
                "title": "빌어먹을 환생 - 네이버 시리즈",
                "url": naver_url,
                "content": "이 장르의 인기 웹소설. 빌어먹을 환생 프로젝트J.",
            },
        ]
        ctx = ConversationContext(
            post_id=11718099,
            post_data={"post_id": 11718099, "title": "빌환 표지변경됨"},
            comments=[],
        )
        ctx.search_results = search_results

        self.assertTrue(
            pipeline._is_title_matched_non_novel_media_url(title, kakao_webtoon_url, search_results)
        )
        self.assertIsNone(
            pipeline._title_matched_official_url_quality(title, kakao_webtoon_url, search_results)
        )
        self.assertEqual(
            pipeline._find_title_matched_official_url(title, search_results),
            naver_url,
        )

        ev = pipeline._evaluate_heretic_url_candidate(
            kakao_webtoon_url,
            ctx=ctx,
            search_results=search_results,
            identified_title=title,
            identified_author=None,
        )
        self.assertFalse(ev["valid"])
        self.assertEqual(ev["invalid_reason"], "non_novel_media_platform_detail")

        frozen = pipeline._freeze_identity_references(
            ctx=ctx,
            is_relevant=True,
            official_title=title,
            heretic_url=kakao_webtoon_url,
            confidence="High",
            topicality="core_relevant",
            work_resolution="resolved",
            title_candidates=[
                DetectedTitle(
                    official_title=title,
                    heretic_url=kakao_webtoon_url,
                    confidence="High",
                    source_tier="official_detail",
                )
            ],
            primary_work=DetectedTitle(
                official_title=title,
                heretic_url=kakao_webtoon_url,
                confidence="High",
                source_tier="official_detail",
            ),
            mentioned_works=[],
            comparison_target=None,
            recommendation_candidates=[],
            future_watch_target=None,
            anchor_type="title_alias",
            consistency_flags=[],
        )

        self.assertEqual(frozen["heretic_url"], naver_url)
        self.assertEqual(frozen["primary_work"].heretic_url, naver_url)
        self.assertIn("non_novel_media_url_cleared", frozen["consistency_flags"])
        self.assertIn("official_detail_url_repaired_from_search", frozen["consistency_flags"])

    def test_heretic_url_validator_rejects_official_page_title_mismatch(self):
        pipeline = _build_pipeline()
        title = "아카데미의 피해자"
        wrong_url = "https://page.kakao.com/content/61802484?tab_type=about"
        wrong_page_title = "회귀 이단심문관의 악마 사냥법"
        ctx = ConversationContext(
            post_id=11718117,
            post_data={
                "post_id": 11718117,
                "title": "이거 제목좀",
                "content_blocks": [
                    {
                        "type": "image",
                        "ocr_text": "아카데미의 피해자 양파랑",
                    }
                ],
            },
            comments=[],
        )
        ctx.search_results = [
            {
                "rank": 1,
                "title": f"{wrong_page_title} - 웹소설 | 카카오페이지",
                "url": wrong_url,
                "content": "아카데미의 피해자 양파랑 관련 검색 스니펫",
            }
        ]
        ctx.fetched_page_info = [
            {
                "url": wrong_url,
                "structured_info": {
                    "title": wrong_page_title,
                    "page_title": f"{wrong_page_title} - 웹소설 | 카카오페이지",
                    "page_type": "novel_page",
                    "content_status": "active",
                },
                "text_preview": wrong_page_title,
            }
        ]

        ev = pipeline._evaluate_heretic_url_candidate(
            wrong_url,
            ctx=ctx,
            search_results=ctx.search_results,
            identified_title=title,
            identified_author="양파랑",
        )

        self.assertFalse(ev["valid"])
        self.assertEqual(ev["invalid_reason"], "url_title_mismatch")
        self.assertEqual(ev["representative_title"], wrong_page_title)
        self.assertIsNone(
            pipeline._validate_heretic_url(wrong_url, ctx, identified_title=title)
        )

        frozen = pipeline._freeze_identity_references(
            ctx=ctx,
            is_relevant=True,
            official_title=title,
            heretic_url=wrong_url,
            confidence="High",
            topicality="core_relevant",
            work_resolution="resolved",
            title_candidates=[
                DetectedTitle(
                    official_title=title,
                    heretic_url=wrong_url,
                    confidence="High",
                    source_tier="official_detail",
                )
            ],
            primary_work=DetectedTitle(
                official_title=title,
                heretic_url=wrong_url,
                confidence="High",
                source_tier="official_detail",
            ),
            mentioned_works=[],
            comparison_target=None,
            recommendation_candidates=[],
            future_watch_target=None,
            anchor_type="image_ocr",
            consistency_flags=[],
        )

        self.assertIsNone(frozen["heretic_url"])
        self.assertIsNone(frozen["primary_work"].heretic_url)
        self.assertIsNone(frozen["title_candidates"][0].heretic_url)
        self.assertIn("url_title_mismatch", frozen["primary_work"].negative_evidence)
        self.assertIn("official_detail_url_title_mismatch_cleared", frozen["consistency_flags"])

