    def test_unavailable_exact_search_title_survives_stale_representative_title(self):
        pipeline = _build_pipeline()
        title = "두바이의 쫀득한 여초딩 재벌 9세"
        stale_title = "전세계가 집착하는 초천재 헌터가 되었다 아주 긴 대표 제목"
        novelpia_url = "https://novelpia.com/novel/419119"
        ctx = ConversationContext(
            post_id=11661853,
            post_data={
                "post_id": 11661853,
                "title": "두바 노벨피아",
                "content_blocks": [{"type": "text", "text": "TS 인방물 재벌 9세 얘기"}],
            },
            comments=[],
        )
        ctx.search_results = [
            {
                "rank": 1,
                "title": f"웹소설로 꿈꾸는 세상! - {title} - 노벨피아",
                "url": novelpia_url,
                "content": "노벨피아 플러스 독점 웹소설.",
                "_trust_score": 0.9,
                "_purpose": "title_body_sanitized_platform_probe",
                "_query": "두바 노벨피아",
            },
            {
                "rank": 2,
                "title": stale_title,
                "url": novelpia_url,
                "content": "오래된 검색 캐시의 대표 제목.",
                "_trust_score": 0.9,
            },
        ]
        ctx.fetched_page_info = [
            {
                "url": novelpia_url,
                "_content_deleted": True,
                "structured_info": {
                    "content_status": "unavailable",
                    "content_status_source": "llm",
                    "title": "403 Forbidden",
                    "page_title": "로그인 후 이용 가능합니다",
                    "page_type": "novel_page",
                },
                "text_preview": "로그인 후 이용 가능합니다",
            }
        ]

        ev = pipeline._evaluate_heretic_url_candidate(
            novelpia_url,
            ctx=ctx,
            search_results=ctx.search_results,
            identified_title=title,
            identified_author=None,
        )

        self.assertTrue(ev["valid"], ev)
        self.assertTrue(ev["title_evidence"], ev)
        self.assertTrue(ev["fetch_unavailable_search_exact_fallback"], ev)
        self.assertEqual(ev["representative_title"], stale_title)
        quality = pipeline._collect_title_source_quality(ctx, title)
        self.assertFalse(quality["severe_negative"], quality)
        self.assertEqual(quality["deleted_detail_match_count"], 0, quality)
        self.assertEqual(quality["unavailable_exact_search_fallback_count"], 1, quality)
        self.assertGreaterEqual(quality["active_detail_match_count"], 1, quality)
        self.assertIn(
            novelpia_url,
            pipeline._official_detail_exact_title_urls_for_no_work_anchor(ctx, title),
        )

