    def test_low_specificity_connective_alias_does_not_rescue_batch_memory_title(self):
        class Resolver:
            enabled = True

            def resolve_abbreviation_surface(self, surface):
                if "그러는데" in str(surface or ""):
                    return {
                        "title": "어느날",
                        "alias": "그러는데",
                        "confidence": 3,
                        "source": "test_batch_memory",
                    }
                return None

        pipeline = _build_pipeline()
        pipeline.batch_context = Resolver()
        ctx = ConversationContext(
            post_id=11716499,
            post_data={
                "post_id": 11716499,
                "title": "님들 제가 영어 잘 못해서 그러는데 뭔 뜻임?",
                "content_blocks": [
                    {
                        "type": "ocr_text",
                        "text": "[이미지 OCR] 그러자 더는 버티지 못하고 튀어나오고 만 악마.",
                    }
                ],
            },
            comments=[],
        )
        ctx.set_expert_output(
            ExpertType.GATEKEEPER,
            {
                "detected_entities": {"possible_titles": ["그러는데"]},
                "key_terms": ["그러는데", "악마", "아프리카"],
            },
        )

        self.assertTrue(pipeline._is_low_specificity_rescue_key("그러는데", full_title="어느날"))
        self.assertTrue(pipeline._is_generic_alias_seed("그러는데", full_title="어느날"))
        candidate, hit = pipeline._resolve_batch_memory_alias_candidate(
            ctx,
            verification_result={
                "grounding_check": {"anchor_found": "none"},
                "counter_arguments": [
                    {
                        "severity": "critical",
                        "issue": "제목은 영어 뜻 질문이고 공식 작품 제목은 원문에 없다.",
                    }
                ],
            },
        )

        self.assertIsNone(candidate)
        self.assertIsNone(hit)

