    def test_orchestrator_sanitize_verification_queries_prefers_partial_title_anchor(self):
        orchestrator = Orchestrator(experts={}, search_fn=None, fetch_fn=None)
        ctx = ConversationContext(
            post_id=7772,
            post_data={
                "post_id": 7772,
                "title": "와 이거 뭐냐",
                "content_blocks": [{"type": "text", "text": "빙의한 엄마가 아들을 ... 현모양처 이수진"}],
                "image_enrichment": [
                    {
                        "explicit_work_title": "빙의한 엄마가 아들을 ...",
                        "title_role": "work_title",
                        "evidence_type": "explicit_text",
                        "screen_type": "work_surface",
                        "surface_type": "quoted_text_screenshot",
                        "ocr_text": "빙의한 엄마가 아들을 ... 15회차 민혁 지훈 이수진",
                    }
                ],
            },
            comments=[],
        )
        ctx.set_expert_output(
            ExpertType.GATEKEEPER,
            {
                "detected_entities": {
                    "possible_titles": ["빙의한 엄마가 아들을", "현모양처 이수진"],
                    "possible_characters": ["민혁", "지훈", "이수진"],
                }
            },
        )

        queries = [
            '"현모양처 이수진" 웹소설',
            '"민혁" "지훈" "이수진" 웹소설',
            '"빙의한 엄마가 아들을" 웹소설 정식제목',
        ]
        kept = orchestrator._sanitize_verification_queries(
            ctx,
            ExpertType.VERIFIER,
            {},
            queries,
        )

        self.assertIn('"빙의한 엄마가 아들을" 웹소설 정식제목', kept)
        self.assertIn('"민혁" "지훈" "이수진" 웹소설', kept)
        self.assertNotIn('"현모양처 이수진" 웹소설', kept)

