    def test_execute_searches_caps_late_total_budget(self):
        calls = []

        def fake_search(query, purpose=""):
            calls.append((query, purpose))
            return [
                {
                    "title": f"{query} 결과",
                    "url": f"https://novelpia.com/novel/{len(calls)}",
                    "content": f"{query} 공식 작품 페이지",
                }
            ]

        orchestrator = Orchestrator(experts={}, search_fn=fake_search, fetch_fn=None)
        ctx = ConversationContext(
            post_id=502,
            post_data={"post_id": 502, "title": "회귀수선전 질문"},
            comments=[],
        )
        ctx.iteration = 3
        for idx in range(15):
            ctx.mark_executed_query(f"previous query {idx}")

        requests = [
            {"query": "회귀수선전 웹소설 문피아", "purpose": "official_title_verify", "priority": 1},
            {"query": "회귀수선전 웹소설 노벨피아", "purpose": "official_title_verify", "priority": 2},
            {"query": "회귀수선전 리뷰", "purpose": "title_search_community", "priority": 3},
        ]
        with patch.dict(
            "os.environ",
            {
                "LLM_ENABLE_LATE_TOTAL_SEARCH_BUDGET": "1",
                "LLM_ENABLE_LATE_SEARCH_BUDGET": "1",
                "LLM_LATE_TOTAL_SEARCH_MIN_ITERATION": "3",
                "LLM_MAX_TOTAL_SEARCH_QUERIES_UNCERTAIN": "16",
            },
        ):
            results = orchestrator._execute_searches(requests, ctx.post_id, ctx=ctx)

        self.assertEqual(len(calls), 1)
        self.assertEqual(calls[0][0], "회귀수선전 웹소설 문피아")
        self.assertEqual(len(results), 1)
        self.assertEqual(ctx.search_query_stats.get("late_budget_capped_total"), 1)

