        best = pipeline._select_best_canonical_rescue_candidate(ctx=ctx, vf_result=vf)
        self.assertEqual(best["title"], title)
        self.assertTrue((best.get("rescue") or {}).get("deliberated_character_setting_convergence"))
        self.assertFalse(
            pipeline._can_promote_title_after_semantic_no_work(
                ctx,
                title,
                source="unit_deliberated_character_setting_convergence",
                verification_result=vf,
            )
        )
        decision = ctx._last_promotion_gate_decision
        self.assertIs(decision["publish_allowed"], False)
        self.assertIsNone(decision["official_title"])
        self.assertIsNone(decision["official_url"])
        self.assertFalse(decision["bypassed_gate"])

