    def test_search_with_meta_keeps_raw_preview_from_bridge(self):
        pipeline = AgenticPipeline(llm=DummyLLM(), mcp=FakeSearchMetaMCP(), max_iterations=2)

        results, meta = pipeline._search_with_meta('"즉사무림" 정식 명칭', "abbreviation_verification")

        self.assertEqual(len(results), 1)
