        pipeline._has_explicit_webnovel_context = lambda _ctx: False
        pipeline._compute_title_acceptance = lambda *args, **kwargs: {
            "decision": "accept",
            "score": 9,
            "candidate_class": "work_like",
            "relation_type": "explicit_alias",
            "relation_target": "specific_work",
            "relation_promotion": "allow",
            "official_nonwiki_count": 1,
            "notes": ["explicit_alias_specific_work"],
        }

        result = pipeline._apply_output_consistency_validator(
            ctx=ctx,
            is_relevant=True,
            discussion_type="character_talk",
            official_title=title,
            confidence="Medium",
            reason="아집숨은 아포칼립스에 집을 숨김의 약칭이고 박규는 작품 캐릭터로 연결됨",
            notes=None,
            title_candidates=[DetectedTitle(official_title=title, confidence="High")],
            primary_work=DetectedTitle(official_title=title, confidence="High"),
            mentioned_works=[],
            comparison_target=None,
            recommendation_candidates=[],
            metadata={},
            verification_result={
                "is_relevant": True,
                "is_novel_discussion": True,
                "grounding_check": {
                    "anchor_found": "title_reaction_link",
                    "title_abbrev_mentioned": True,
                    "matched_alias": "아집숨",
                },
                "relation_judgment": {
                    "relation_type": "explicit_alias",
                    "discussion_target": "specific_work",
                    "promotion_decision": "allow",
                },
                "counter_arguments": [],
            },
        )

        self.assertTrue(result["is_relevant"])
        self.assertEqual(result["official_title"], title)
        self.assertEqual(result["work_resolution"], "resolved")

