    def test_batch_alias_candidate_rescues_v105_title_and_body_aliases(self):
        import copy
        import json
        from expert_main import load_jsonl_posts

        pipeline = _build_pipeline()
        pipeline.enable_url_fetch_disk_cache = False
        pipeline.enable_heretic_live_fetch = False
        cases = [
            (
                8388455,
                "탑매 이벤트 중이구나",
                "무료분이라도 봐야하나",
                "탑매",
                "탑 매니지먼트",
                None,
                [
                    {
                        "title": "탑 매니지먼트 - 나무위키:대문",
                        "url": "https://namu.wiki/w/%ED%83%91%20%EB%A7%A4%EB%8B%88%EC%A7%80%EB%A8%BC%ED%8A%B8",
                        "content": "탑 매니지먼트. 장르 현대 판타지, 연예계. 작가 장우산. 출판사 문피아. 연재처 문피아.",
                        "query": "탑매 정식 제목",
                    }
                ],
            ),
            (
                11365197,
                "근데 아지는 성이 있는거냐",
                "전1시 애들이 다 고아라 청탑주빼곤 성이 없는데",
                "전1시",
                "전지적 1인칭 시점",
                "https://novelpia.com/novel/49942",
                [
                    {
                        "title": "전지적 1인칭 시점 - 노벨피아",
                        "url": "https://novelpia.com/novel/49942",
                        "content": "전지적 1인칭 시점 웹소설. 약칭 전1시. 장르 판타지. 작가와 연재처 정보.",
                        "query": "전1시 정식 제목",
                    }
                ],
            ),
            (
                10887145,
                "괴출만 없었으면 카카페 ㄹㅇ 망했다고 하는건데",
                "괴출이 너무 잘돼서 망했다기에는 뭔가 묘하긴해",
                "괴출",
                "괴담에 떨어져도 출근을 해야 하는구나",
                "https://page.kakao.com/content/65171279",
                [
                    {
                        "title": "괴담에 떨어져도 출근을 해야 하는구나 - 카카오페이지",
                        "url": "https://page.kakao.com/content/65171279",
                        "content": "괴담에 떨어져도 출근을 해야 하는구나 웹소설. 약칭 괴출. 장르 괴담 판타지.",
                        "query": "괴출 정식 제목",
                    }
                ],
            ),
            (
                9621816,
                "성녀속마음 이거 별로네",
                "문체가 유치함",
                "성녀속마음",
                "성녀의 속마음이 들린다",
                None,
                [],
            ),
        ]

        for post_id, title, body, alias, official_title, expected_url, search_results in cases:
            with self.subTest(post_id=post_id):
                ctx = ConversationContext(
                    post_id=post_id,
                    post_data={
                        "post_id": post_id,
                        "title": title,
                        "content_blocks": [{"type": "text", "text": body}],
                    },
                    comments=[],
                )
                ctx.search_results = search_results
                if post_id == 11365197:
                    # 본문 약칭은 원래 loader/capture를 거쳐 관측 후보로만 보존한다.
                    source = json.dumps(ctx.post_data, ensure_ascii=False).encode('utf-8') + b'\n'
                    post = load_jsonl_posts(Path('synthetic_body_alias.jsonl'), snapshot_bytes=source)[0]
                    ctx.post_data = pipeline._post_to_dict(post)
                    ctx._final_source_original_inputs = pipeline._capture_final_source_original_inputs(post)
                    ctx._input_truncated = post._input_truncated
                    ctx._parse_errors = post._parse_errors
                    before = copy.deepcopy(ctx.post_data)
                    candidate, hit = pipeline._resolve_batch_memory_alias_candidate(ctx, {})
                    self.assertIsNone(candidate)
                    self.assertIsNone(hit)
                    retained, added = pipeline._append_known_title_abbreviation_preservation_candidates(ctx, [])
                    self.assertTrue(added)
                    self.assertEqual(len(retained), 1)
                    observed = retained[0]
                    self.assertEqual(observed.official_title, official_title)
                    self.assertEqual(observed.alias_or_mention, alias)
                    self.assertEqual(observed.reference_role, 'candidate')
                    self.assertFalse(observed.locked)
                    self.assertFalse(observed.resolved_recall_anchor)
                    self.assertIsNone(observed.heretic_url)
                    self.assertEqual(observed.confidence, 'Medium')
                    self.assertIn('source_bound_body_alias_observation_only', observed.negative_evidence)
                    self.assertEqual(ctx.post_data, before)
                    observed_before = copy.deepcopy(observed.model_dump(mode="json"))
                    recall_source = copy.deepcopy(search_results[0])
                    output = pipeline._context_to_output(ctx)
                    inventory_diagnostic = json.dumps({
                        "case": "r6_rework_04_body_alias", "identity": output.identity.model_dump(mode="json")},
                        ensure_ascii=False, sort_keys=True)
                    print("[r6_rework_inventory] " + inventory_diagnostic, file=sys.stderr)
                    self.assertIsNone(output.identity.novel_identity)
                    self.assertFalse((output.identity.promotion_decision or {}).get('publish_allowed', False))
                    # 초기 제목 생성 snapshot은 후기 보존 후보의 최종 목록이 아니다.
                    sources = output.identity.candidate_preservation_sources or []
                    observed_sources = [item for item in sources if item.get("official_title") == official_title]
                    self.assertTrue(observed_sources, inventory_diagnostic)
                    # 최종 목록은 직접 helper 반환물이 아니라 검색 recall 이후의 후보다.
                    # 정확한 원문/검색 쌍을 보존하되 공개 권한은 계속 HOLD여야 한다.
                    self.assertTrue(any(item.get("heretic_url") == expected_url
                        and item.get("source_tier") == "official_detail"
                        and item.get("page_type") == "novel_page"
                        and item.get("preservation_role") == "title_candidate"
                        for item in observed_sources), inventory_diagnostic)
                    source_evidence = [item for item in (output.identity.search_evidence_catalog or [])
                        if item.get("url") == expected_url]
                    self.assertEqual(len(source_evidence), 1, inventory_diagnostic)
                    evidence = source_evidence[0]
                    self.assertEqual(evidence.get("title"), recall_source["title"], inventory_diagnostic)
                    self.assertEqual(evidence.get("query"), recall_source["query"], inventory_diagnostic)
                    self.assertEqual(evidence.get("snippet"), recall_source["content"], inventory_diagnostic)
                    self.assertEqual(evidence.get("source_tier"), "novel_platform", inventory_diagnostic)
                    self.assertTrue(evidence.get("eid"), inventory_diagnostic)
                    self.assertIn(alias, body)
                    self.assertIn(f"약칭 {alias}", evidence["snippet"], inventory_diagnostic)
                    self.assertIn("official_url_recall_gate_recovered", output.identity.consistency_flags)
                    self.assertIn(f"confirmed_alias:{alias}", output.identity.consistency_flags)
                    final_candidates = [item for item in (output.identity.title_candidates or [])
                        if item.official_title == official_title and item.heretic_url == expected_url]
                    self.assertTrue(final_candidates, inventory_diagnostic)
                    for final_candidate in final_candidates:
                        self.assertEqual(final_candidate.reference_role, "candidate", inventory_diagnostic)
                        self.assertIsNot(final_candidate.locked, True, inventory_diagnostic)
                        self.assertIsNot(final_candidate.resolved_recall_anchor, True, inventory_diagnostic)
                    gate = output.identity.promotion_decision or {}
                    self.assertIs(gate.get("publish_allowed"), False, inventory_diagnostic)
                    self.assertIs(gate.get("bypassed_gate"), False, inventory_diagnostic)
                    self.assertIs(gate.get("candidate_preserved"), True, inventory_diagnostic)
                    self.assertIsNone(gate.get("official_title"), inventory_diagnostic)
                    self.assertIsNone(gate.get("official_url"), inventory_diagnostic)
                    self.assertIs(output.identity.title_resolution_allowed, False, inventory_diagnostic)
                    self.assertEqual(output.identity.work_resolution, "unresolved", inventory_diagnostic)
                    self.assertEqual(output.identity.title_resolution_state, "unresolved_matchable", inventory_diagnostic)
                    preservation_evidence = [item for item in (output.identity.promotion_gate_evidence or [])
                        if item.get("kind") == "candidate_preservation"
                        and item.get("candidate_title") == official_title
                        and item.get("candidate_url") == expected_url]
                    self.assertTrue(preservation_evidence, inventory_diagnostic)
                    self.assertTrue(all(item.get("supports_publish") is False
                        for item in preservation_evidence), inventory_diagnostic)
                    # 직접 관측 helper의 무URL/비권한 반환값 자체도 이후에 변조되지 않는다.
                    self.assertEqual(observed.model_dump(mode="json"), observed_before)
                    final_generation = (output.identity.candidate_ledger or {}).get("candidate_generation") or {}
                    self.assertEqual(final_generation.get("emitted_source_count"), len(sources), inventory_diagnostic)
                    continue
                candidate, hit = pipeline._resolve_batch_memory_alias_candidate(ctx, verification_result={})
                if search_results:
                    self.assertIsNotNone(candidate)
                    self.assertIsNotNone(hit)
                    self.assertEqual(hit["alias"], alias)
                    self.assertEqual(candidate.official_title, official_title)
                    self.assertEqual(candidate.heretic_url, expected_url)
                else:
                    self.assertIsNone(candidate)
                    self.assertIsNone(hit)

