    def test_final_title_guard_demotes_title_when_arbiter_says_existing_non_webnovel_media(self):
        pipeline = _build_pipeline()
        title = "강철의 연금술사"
        post = PostInput(
            post_id=8531521,
            title="강연금 알렉형제는 강한편이긴 한데",
            created_at="2024-04-14 01:36:49",
            content_blocks=[ContentBlock(type="text", text="상대적으로 좆밥같아보임")],
            comments=["대령은 비오면 무능하잖아"],
        )
        ctx = ConversationContext(post_id=8531521, post_data=pipeline._post_to_dict(post), comments=post.comments)
        ctx.set_expert_output(
            ExpertType.DISCOURSE,
            {
                "discourse_analysis": {
                    "primary_domain": "novel_literature",
                    "domain_confidence": "medium",
                    "secondary_domains": ["manga_comics"],
                    "intent": "discuss_work",
                }
            },
        )
        ctx.set_expert_output(
            ExpertType.ARBITER,
            {
                "final_decision": {"official_novel_title": title},
                "final_reasoning": (
                    "이 글은 특정 웹소설 작품에 대해 이야기하는 것이 아니라, "
                    "'강철의 연금술사'라는 기존 미디어 믹스 작품의 캐릭터와 설정을 논한다."
                ),
            },
        )

        result = pipeline._apply_output_consistency_validator(
            ctx=ctx,
            is_relevant=True,
            discussion_type="character_talk",
            official_title=title,
            confidence="High",
            reason="강연금 캐릭터 토론",
            notes=None,
            title_candidates=[DetectedTitle(official_title=title, confidence="High")],
            primary_work=DetectedTitle(official_title=title, confidence="High"),
            mentioned_works=[],
            comparison_target=None,
            recommendation_candidates=[],
            metadata={},
            verification_result={
                "is_relevant": True,
                "is_novel_discussion": True,
                "grounding_check": {"anchor_found": "character_mention"},
                "counter_arguments": [],
            },
        )

        self.assertFalse(result["is_relevant"])
        self.assertIsNone(result["official_title"])
        self.assertEqual(result["work_resolution"], "none")
        self.assertIn("non_novel_media_title_demoted", result["consistency_flags"])

