    def test_expression_surface_becomes_packet_local_semantic_reread_hint(self):
        pipeline = _build_pipeline()
        post = PostInput(
            post_id=11718091,
            title="소신발언)) 은영이 23센줄 몰랐음",
            author="ㅇㅇ",
            content_blocks=[ContentBlock(type="text", text="묘사만 보면 한 16살인줄???")],
            comments=["ㄹㅇ 머리도 안올렷잖아 더어린줄"],
        )

        post_data = pipeline._post_to_dict(post)
        notes = post_data.get("surface_paraphrase_notes") or []
        sources = {note.get("source_surface") for note in notes}

        self.assertIn("23센줄", sources)
        self.assertIn("16살인줄", sources)
        self.assertTrue(all(note.get("kind") == "expression_typo_abbreviation_or_spacing_candidate" for note in notes))
        self.assertTrue(all(not note.get("paraphrase") for note in notes))
        self.assertTrue(
            all(note.get("role") == "non_title_semantic_context" for note in notes)
        )
        self.assertTrue(
            all(note.get("scope") == "packet_local_reread_hint" for note in notes)
        )
        self.assertTrue(
            all(note.get("evidence_role") == "not_title_or_alias_evidence" for note in notes)
        )
        self.assertTrue(
            all(
                note.get("pattern_scope") == "generic_expression_typo_abbreviation_spacing_pattern"
                for note in notes
            )
        )
        self.assertTrue(
            all(note.get("rule_scope") == "not_surface_specific_rule" for note in notes)
        )

        generic_post = PostInput(
            post_id=1171809101,
            title="주인공 31센줄 몰랐음",
            author="ㅇㅇ",
            content_blocks=[ContentBlock(type="text", text="묘사만 보면 한 19살인줄")],
            comments=[],
        )
        generic_notes = pipeline._post_to_dict(generic_post).get("surface_paraphrase_notes") or []
        generic_sources = {note.get("source_surface") for note in generic_notes}
        self.assertIn("31센줄", generic_sources)
        self.assertIn("19살인줄", generic_sources)
        self.assertTrue(all(not note.get("paraphrase") for note in generic_notes))
        self.assertTrue(
            all(note.get("scope") == "packet_local_reread_hint" for note in generic_notes)
        )

        discourse_post = DiscourseAnalyzer(DummyLLM())._build_post_json(
            post_data,
            pipeline._extract_comments(post),
        )
        self.assertIn("surface_paraphrase_notes", discourse_post)
        self.assertIn("23센줄", str(discourse_post["surface_paraphrase_notes"]))
        self.assertNotIn("23세인 줄", str(discourse_post["surface_paraphrase_notes"]))

        sanitized = DiscourseAnalyzer(DummyLLM())._sanitize_result(
            {
                "discourse_analysis": {
                    "primary_domain": "novel_literature",
                    "intent": "discuss_work",
                    "speech_act": "review",
                    "target_kind": "work",
                    "title_novel_terms": ["은영", "23센줄"],
                    "domain_evidence": ["은영", "23센줄", "16살"],
                    "semantic_seed_review": {
                        "content_interpretation": "표현 오타/축약 패턴(범용)으로만 재해독하며, 작품명 후보가 아니다.",
                        "is_specific_work_discussion": False,
                    },
                    "search_suggestions": [
                        {"query": "은영 23세", "purpose": "character/work probe", "priority": 1},
                        {"query": "16살인줄 묘사", "purpose": "surface phrase probe", "priority": 2},
                    ],
                }
            },
            post_json=discourse_post,
        )
        da = sanitized["discourse_analysis"]
        self.assertEqual(da["title_novel_terms"], [])
        self.assertEqual(da["intent"], "express_opinion")
        self.assertEqual(da["target_kind"], "unknown")
        self.assertIn("23센줄", da["surface_paraphrase_context_terms"])
        self.assertIn("은영", da["surface_paraphrase_context_terms"])
        self.assertEqual(da["search_suggestions"], [])
        self.assertIn("surface_paraphrase_search_suggestions_removed", da["warnings"])
        self.assertIn("surface_paraphrase_specific_work_denied", da["warnings"])
        self.assertFalse(da["semantic_seed_review"]["is_specific_work_discussion"])

    def test_surface_paraphrase_runs_semantic_review_without_title_seed(self):
        fake_llm = FakeSemanticSeedReviewLLM(
            """
            {
              "post_intent": "직접 작품 앵커가 약한 짧은 반응이다.",
              "content_interpretation": "표현 오타/축약 패턴(범용)이며 작품명 후보가 아니다.",
              "is_specific_work_discussion": false,
              "recommended_intent": "express_opinion",
              "recommended_target_kind": "character",
              "title_seed_reviews": [],
              "search_query_reviews": [],
              "warnings": ["surface_paraphrase_context_only"]
            }
            """
        )
        discourse = DiscourseAnalyzer(fake_llm)
        post_json = {
            "post_id": 11718091,
            "title": "소신발언)) 은영이 23센줄 몰랐음",
            "content": ["묘사만 보면 한 16살인줄???"],
            "comments": ["ㄹㅇ 머리도 안올렷잖아 더어린줄"],
            "surface_paraphrase_notes": [
                {
                    "kind": "expression_typo_abbreviation_or_spacing_candidate",
                    "source_surface": "23센줄",
                    "role": "non_title_semantic_context",
                    "interpretation": "packet_local_expression_reread_candidate",
                }
            ],
        }

        sanitized = discourse._sanitize_result(
            {
                "discourse_analysis": {
                    "primary_domain": "novel_literature",
                    "intent": "discuss_work",
                    "speech_act": "review",
                    "target_kind": "work",
                    "title_novel_terms": [],
                    "search_suggestions": [],
                }
            },
            post_json=post_json,
        )

        self.assertEqual(len(fake_llm.calls), 1)
        user_message = (fake_llm.calls[0]["kwargs"].get("messages") or [])[1]["content"]
        self.assertIn("surface_paraphrase_notes", user_message)
        self.assertIn("23센줄", user_message)
        self.assertIn("expression_typo_abbreviation_or_spacing_candidate", user_message)
        da = sanitized["discourse_analysis"]
        self.assertEqual(da["intent"], "express_opinion")
        self.assertEqual(da["target_kind"], "character")
        self.assertFalse(da["semantic_seed_review"]["is_specific_work_discussion"])
        self.assertIn("표현 오타/축약 패턴(범용)", da["semantic_seed_review"]["content_interpretation"])
        self.assertIn("semantic_seed_review_specific_work_denied", da["warnings"])

    def test_final_semantic_reread_rejects_search_promotion_after_context_only_review(self):
        fake_llm = FakeFinalSemanticRereadLLM(
            """
            {
              "decision": "REJECT",
              "is_specific_work_discussion": false,
              "evidence_strength": "Weak",
              "recommended_discussion_type": "community_banter",
              "reason": "표현 오타/축약 패턴(범용)은 검색 후보를 직접 지지하지 않는다."
            }
            """
        )
        pipeline = AgenticPipeline(llm=fake_llm, mcp=DummyMCP(), max_iterations=2)
        post_json = {
            "post_id": 11718091,
            "title": "소신발언)) 은영이 23센줄 몰랐음",
            "content_blocks": [{"type": "text", "text": "묘사만 보면 한 16살인줄???"}],
            "surface_paraphrase_notes": [
                {
                    "source_surface": "23센줄",
                    "role": "non_title_semantic_context",
                }
            ],
        }
        ctx = ConversationContext(
            post_id=11718091,
            post_data=post_json,
            comments=["ㄹㅇ 머리도 안올렷잖아 더어린줄"],
        )
        ctx.discourse_warning = "semantic_seed_review(no_work_anchor)"
        ctx.search_results = [
            {
                "_evidence_id": "E001",
                "title": "네이버 웹소설 검색 결과",
                "url": "https://example.test/search",
                "content": "검색어 일부만 겹치는 결과",
            }
        ]
        ctx.set_expert_output(
            ExpertType.DISCOURSE,
            {
                "discourse_analysis": {
                    "intent": "express_opinion",
                    "target_kind": "character",
                    "semantic_seed_review": {
                        "content_interpretation": "표현 오타/축약 패턴(범용)으로 재검토해야 하는 비제목 자연어 표현이다.",
                        "is_specific_work_discussion": False,
                    },
                    "warnings": [
                        "semantic_seed_review_specific_work_denied",
                        "surface_paraphrase_non_title_terms_removed",
                    ],
                }
            },
        )

        review = pipeline._run_final_semantic_reread(
            ctx=ctx,
            is_relevant=True,
            official_title="네이버",
            discussion_type="general",
            verification_result={
                "is_relevant": True,
                "grounding_check": {"anchor_found": "search_only"},
            },
            final_decision={"is_relevant": True, "official_title": "네이버"},
        )
        action = pipeline._final_semantic_reread_action(review)

        self.assertEqual(review["decision"], "REJECT")
        self.assertTrue(action["changed"])
        self.assertEqual(action["discussion_type"], "community_banter")
        self.assertIn("final_semantic_reread_rejected_resolution", action["flags"])
        self.assertEqual(fake_llm.calls[0]["kwargs"].get("tag"), "final_semantic_reread")
        user_message = (fake_llm.calls[0]["kwargs"].get("messages") or [])[1]["content"]
        self.assertIn("표현 오타/축약 패턴(범용)", user_message)
        self.assertNotIn("23세인 줄", user_message)
        self.assertIn("네이버", user_message)
        self.assertIn("표현 오타/축약 패턴(범용)", action["reason"])

