    def test_semantic_seed_review_demotes_short_banter_terms_before_search(self):
        fake_llm = FakeSemanticSeedReviewLLM(
            """
            {
              "post_intent": "직접 작품 앵커가 약한 짧은 반응이다.",
              "content_interpretation": "유미아는 이 문맥에서 검색 seed가 아니라 외모 감상의 대상 인명처럼 쓰였다.",
              "is_specific_work_discussion": false,
              "recommended_intent": "express_opinion",
              "recommended_target_kind": "character",
              "title_seed_reviews": [
                {"surface": "유미아", "decision": "context_only", "confidence": "high", "reason": "작품명 확정 근거 없이 외모 감상 대상으로 쓰임"}
              ],
              "search_query_reviews": [
                {"query": "유미아 웹소설", "decision": "drop", "confidence": "high", "reason": "감상 인명을 작품 검색으로 확장함"}
              ],
              "warnings": ["short_banter_seed_demoted"]
            }
            """
        )
        discourse = DiscourseAnalyzer(fake_llm)
        post_json = {
            "post_id": 1,
            "title": "소신발언)) 유미아 너무 어려보임",
            "content": ["성인 캐릭이라니"],
            "comments": ["그냥 외모 감상임"],
            "comment_context": ["#1 speaker=post_author author=ㅇㅇ role=post_author comment_id=1"],
            "comment_dialogue_context": [
                "#1 speaker=post_author author=ㅇㅇ role=post_author comment_id=1 text=그냥 외모 감상임"
            ],
        }

        sanitized = discourse._sanitize_result(
            {
                "discourse_analysis": {
                    "primary_domain": "novel_literature",
                    "intent": "discuss_work",
                    "speech_act": "review",
                    "target_kind": "work",
                    "title_novel_terms": ["유미아"],
                    "domain_evidence": ["유미아", "성인 캐릭"],
                    "search_suggestions": [
                        {"query": "유미아 웹소설", "purpose": "title_search", "priority": 1},
                    ],
                }
            },
            post_json=post_json,
        )

        da = sanitized["discourse_analysis"]
        self.assertEqual(da["title_novel_terms"], [])
        self.assertEqual(da["search_suggestions"], [])
        self.assertEqual(da["intent"], "express_opinion")
        self.assertEqual(da["target_kind"], "character")
        self.assertIn("유미아", da["semantic_seed_review_context_terms"])
        self.assertIn("semantic_seed_review_non_title_terms_removed", da["warnings"])
        self.assertIn("semantic_seed_review_search_suggestions_removed", da["warnings"])
        self.assertIn("semantic_seed_review_specific_work_denied", da["warnings"])
        self.assertFalse(da["semantic_seed_review"]["is_specific_work_discussion"])
        self.assertEqual(fake_llm.calls[0]["kwargs"].get("tag"), "discourse_semantic_seed_guard")
        user_message = (fake_llm.calls[0]["kwargs"].get("messages") or [])[1]["content"]
        self.assertIn("comment_dialogue_context", user_message)
        self.assertIn("speaker=post_author", user_message)
        self.assertIn("대화 흐름 메타이지 작품명/별칭/공식 근거가 아닙니다", user_message)

        ctx = ConversationContext(post_id=1, post_data=post_json, comments=post_json["comments"])
        ctx.set_expert_output(ExpertType.DISCOURSE, sanitized)
        gatekeeper_result = {
            "post_type": "short_reaction",
            "detected_entities": {"possible_titles": ["유미아"], "possible_characters": ["유미아"]},
            "key_terms": ["유미아"],
        }
        ctx.set_expert_output(ExpertType.GATEKEEPER, gatekeeper_result)
        orch = Orchestrator(experts={}, search_fn=lambda *_args, **_kwargs: [], fetch_fn=None)
        self.assertTrue(orch._has_discourse_semantic_seed_demotion(ctx))
        self.assertFalse(orch._post_has_image_or_vlm_context(ctx))
        self.assertEqual(orch._derive_auto_search_seed_terms(ctx, gatekeeper_result, limit=4), [])

        image_ctx = ConversationContext(
            post_id=1,
            post_data={**post_json, "image_urls": ["https://example.test/image.png"]},
            comments=post_json["comments"],
        )
        self.assertTrue(orch._post_has_image_or_vlm_context(image_ctx))

