    def test_non_relevant_reason_exposes_age_typo_surface_reading(self):
        pipeline = _build_pipeline()
        post_json = {
            "post_id": 11718091,
            "title": "소신발언)) 은영이 23센줄 몰랐음",
            "content": ["묘사만 보면 한 16살인줄???"],
            "comments": ["ㄹㅇ 머리도 안올렷잖아 더어린줄"],
            "surface_paraphrase_notes": [
                {
                    "kind": "expression_typo_abbreviation_or_spacing_candidate",
                    "source_surface": "23센줄",
                    "role": "non_title_semantic_context",
                    "interpretation": "packet_local_expression_reread_candidate",
                },
                {
                    "kind": "expression_typo_abbreviation_or_spacing_candidate",
                    "source_surface": "16살인줄",
                    "role": "non_title_semantic_context",
                    "interpretation": "packet_local_expression_reread_candidate",
                },
            ],
        }
        ctx = ConversationContext(post_id=11718091, post_data=post_json, comments=post_json["comments"])
        ctx.set_expert_output(
            ExpertType.DISCOURSE,
            {
                "discourse_analysis": {
                    "intent": "express_opinion",
                    "target_kind": "character",
                    "semantic_seed_review": {
                        "post_intent": "직접 작품 앵커가 약한 짧은 반응이다.",
                        "content_interpretation": (
                            "제목과 본문에 등장하는 '은영'이나 '23센줄'은 작품 고유의 "
                            "명확한 앵커가 부족하며, 일반적인 반응이나 표면적 단어에 가까움."
                        ),
                        "is_specific_work_discussion": False,
                    },
                    "semantic_seed_review_context_terms": ["은영이", "23센줄"],
                    "surface_paraphrase_context_terms": ["은영이", "23센줄"],
                    "warnings": [
                        "semantic_seed_review_non_title_terms_removed",
                        "surface_paraphrase_non_title_terms_removed",
                    ],
                }
            },
        )

        reason = pipeline._format_non_relevant_reason(
            discussion_type="noise",
            rejection_reason="",
            verifier_reason="",
            arbiter_reason="",
            grounding_issue="",
            counter_arguments=[],
            ctx=ctx,
            verification_result={},
            final_decision={"is_relevant": False},
        )

        self.assertIn("표현 오타/축약 패턴(범용)은 packet-local 원문 재검토 신호", reason)
        self.assertIn("표현 오타/축약 패턴(범용)은 작품명/별칭 근거가 아니다", reason)
        legacy_reread_label = "\ubc94\uc6a9 \uc7ac\ud574\ub3c5 \ud6c4\ubcf4"
        legacy_spacing_label = "\ud45c\ud604 \uc624\ud0c0/\ucd95\uc57d/\ub744\uc5b4\uc4f0\uae30 \uac00\ub2a5\uc131"
        legacy_possibility_label = "\ud45c\ud604 \uc624\ud0c0/\ucd95\uc57d \uac00\ub2a5\uc131"
        self.assertNotIn(f"의미 재검토: 표현 오타/축약 패턴({legacy_reread_label})으로만 보며", reason)
        self.assertNotIn("표현 오타/축약 패턴(범용):", reason)
        self.assertNotIn("표현 오타/축약 패턴(범용): 23센줄; 16살인줄", reason)
        self.assertNotIn(legacy_spacing_label, reason)
        self.assertNotIn(legacy_possibility_label, reason)
        self.assertNotIn("표면 계열", reason)
        self.assertNotIn("의미 재검토: 제목과 본문에 등장하는 '은영'이나 '23센줄'", reason)
        self.assertNotIn("23세인 줄", reason)
        self.assertNotIn("23세/16세", reason)
        self.assertNotIn("작품 seed 제외: 은영이", reason)
        self.assertNotIn("작품 seed 제외: 은영이, 23센줄", reason)
        self.assertNotIn("seed 후보(은영이)", reason)
        self.assertNotIn("은영이은", reason)

