    def test_expression_reread_surface_is_not_promoted_to_search_seed(self):
        pipeline = _build_pipeline()
        orch = Orchestrator(experts={}, search_fn=lambda *_args, **_kwargs: [], fetch_fn=None)
        post = PostInput(
            post_id=11718091,
            title="소신발언)) 은영이 23센줄 몰랐음",
            author="ㅇㅇ",
            content_blocks=[ContentBlock(type="text", text="묘사만 보면 한 16살인줄???")],
            comments=["ㄹㅇ 머리도 안올렷잖아 더어린줄"],
        )
        ctx = ConversationContext(
            post_id=11718091,
            post_data=pipeline._post_to_dict(post),
            comments=pipeline._extract_comments(post),
        )
        gatekeeper_result = {
            "post_type": "short_reaction",
            "detected_entities": {
                "possible_titles": ["23센줄", "소신발언)) 은영이 23센줄 몰랐음"],
                "possible_characters": ["은영"],
            },
            "key_terms": ["23센줄", "은영 23센"],
        }
        ctx.set_expert_output(ExpertType.GATEKEEPER, gatekeeper_result)

        self.assertTrue(orch._is_low_specificity_search_seed("23센줄"))
        self.assertTrue(
            orch._is_surface_expression_non_title_query(
                "은영 23센 소설",
                ctx=ctx,
                gatekeeper_result=gatekeeper_result,
            )
        )
        self.assertTrue(
            orch._is_surface_expression_non_title_query(
                "은영이 정식 제목",
                ctx=ctx,
                gatekeeper_result=gatekeeper_result,
            )
        )
        self.assertTrue(
            orch._is_surface_expression_non_title_query(
                "은영이 캐릭터",
                ctx=ctx,
                gatekeeper_result=gatekeeper_result,
            )
        )
        self.assertTrue(
            orch._is_surface_expression_non_title_query(
                "소신발언은영",
                ctx=ctx,
                gatekeeper_result=gatekeeper_result,
            )
        )
        pruned = orch._prune_low_specificity_seed_search_requests(
            ctx,
            [
                {"query": "23센줄", "purpose": "title_anchor_exact_probe"},
                {"query": "23센줄 웹소설", "purpose": "title_anchor_official_probe"},
                {"query": "은영 23센 소설", "purpose": "title_search_community"},
                {"query": "은영 16살 묘사", "purpose": "discourse_suggestion"},
                {"query": "23센 줄임말 뜻", "purpose": "alias_raw_probe"},
                {"query": "은영이 정식 제목", "purpose": "title_search_community"},
                {"query": "은영이 캐릭터", "purpose": "character_verify"},
                {"query": "소신발언은영", "purpose": "alias_raw_probe"},
            ],
            gatekeeper_result=gatekeeper_result,
        )
        self.assertEqual([item.get("query") for item in pruned], [])

        seeds = orch._derive_auto_search_seed_terms(ctx, gatekeeper_result, limit=4)
        self.assertEqual(seeds, [])

        verification_queries = orch._sanitize_verification_queries(
            ctx,
            ExpertType.DECODER,
            {"decoded_terms": []},
            ["23센 줄 몰랐음 소설", "은영 웹소설"],
        )
        self.assertEqual(verification_queries, [])

    def test_resolved_title_followup_runs_when_unrelated_official_hint_exists(self):
        orch = Orchestrator(experts={}, search_fn=lambda *_args, **_kwargs: [], fetch_fn=None)
        search_results = [
            {
                "title": "망겜의 힐러 (r15 판) - 나무위키:대문",
                "url": "https://namu.wiki/w/%EB%A7%9D%EA%B2%9C%EC%9D%98%20%ED%9E%90%EB%9F%AC",
                "content": "망겜힐은 검미성 작가의 웹소설 망겜의 힐러를 부르는 약칭이다.",
            },
            {
                "title": "오, 행복 - 웹소설 - 카카오페이지",
                "url": "https://page.kakao.com/content/48688616",
                "content": "로맨스 웹소설. 오행복 검색에서 우연히 잡힌 다른 작품.",
            },
        ]
        key_terms = ["망겜힐", "오행복"]
        gatekeeper_result = {
            "post_type": "work_discussion",
            "detected_entities": {"possible_titles": ["망겜힐"], "possible_characters": ["오행복"]},
        }
        hints = orch._extract_hints_from_snippets(search_results, key_terms)

        self.assertTrue(orch._has_official_like_title_hints(hints))
        requests = orch._extract_resolved_title_followup_queries(
            search_results,
            key_terms,
            gatekeeper_result,
            hints,
            llm_snippet_result={},
        )
        queries = [item.get("query", "") for item in requests]
        self.assertTrue(any("망겜의 힐러" in query for query in queries), queries)
        self.assertFalse(any("오, 행복" in query for query in queries), queries)

