    def test_verifier_detects_embedded_alias_mention_inside_sentence_like_title(self):
        verifier = VerifierExpert(llm_client=DummyLLM())
        post = {
            "title": "말하는 거 보니까 기계공주 잘 읽을 거 같다 ← 뭔 뜻임 이게",
            "content_blocks": [{"type": "text", "text": "하??"}],
        }
        comments = ["고능아", "장빙이 식별코드 보니까 기계공주 완전 잘 어울릴 거 같애!"]
        decoder_result = {
            "decoded_terms": [
                {
                    "original": "말하는 거 보니까 기계공주 잘 읽을 거 같다 ← 뭔 뜻임 이게",
                    "best_match": {"title": "헌터갤러리의 국가권력급 기계공주", "confidence": "high"},
                    "candidates": [
                        {
                            "official_novel_title": "헌터갤러리의 국가권력급 기계공주",
                            "url": "https://novelpia.com/novel/390228",
                        }
                    ],
                }
            ]
        }

        title_in_title, title_in_body, matched_alias = verifier._detect_decoder_alias_mention(
            post,
            comments,
            "헌터갤러리의 국가권력급 기계공주",
            decoder_result,
        )

        self.assertTrue(title_in_title)
        self.assertTrue(title_in_body)
        self.assertEqual(matched_alias, "기계공주")

    def test_decoder_morpheme_rescue_preserves_compound_alias_with_character_suffix(self):
        decoder = DecoderExpert(llm_client=DummyLLM())
        ctx = SimpleNamespace(
            expert_outputs={
                "gatekeeper": {
                    "detected_entities": {
                        "possible_characters": ["이유백"],
                        "possible_authors": [],
                        "possible_titles": ["즉사무림이유백"],
                    }
                }
            },
            post_data={"title": "즉사무림이유백 미래가 벌써 보이네"},
            search_results=[],
        )
        result = {
            "decoded_terms": [
                {
                    "original": "즉사무림이유백",
                    "morphemes": ["즉사무림", "이유백"],
                    "best_match": {
                        "title": "즉사기 들고 무림에 떨어지다",
                        "confidence": "high",
                    },
                    "grounding": {"anchor_type": "title_mention"},
                    "candidates": [
                        {
                            "official_novel_title": "즉사기 들고 무림에 떨어지다",
                            "url": "https://novel.munpia.com/528383",
                        }
                    ],
                    "interpretations": [],
                }
            ]
        }

        validated = decoder._validate_morpheme_in_title(result, ctx)
        decoded_terms = validated.get("decoded_terms") or []
        self.assertTrue(decoded_terms)
        best = decoded_terms[0].get("best_match") or {}
        self.assertIn(str(best.get("confidence") or "").lower(), {"high", "medium"})

    def test_adjacent_author_meta_clears_official_title(self):
        pipeline = _build_pipeline()
        post = PostInput(
            post_id=201,
            title="개돌 신작 유료화 가나",
            author="ㅇㅇ",
            created_at="2026-01-28 18:40:00",
            content_blocks=[ContentBlock(type="text", text="개돌 신작 노벨피아 유료화 가냐")],
            comments=[{"content": "표지부터 뜨겠네"}],
        )
        ctx = ConversationContext(post_id=201, post_data=pipeline._post_to_dict(post), comments=["표지부터 뜨겠네"])
        result = pipeline._apply_output_consistency_validator(
            ctx=ctx,
            is_relevant=False,
            discussion_type="noise",
            official_title="잘못된 단일작",
            confidence="High",
            reason="이 포스트는 웹소설 잘못된 단일작의 유료화 논의다.",
            notes="이 포스트는 웹소설 잘못된 단일작의 유료화 논의다.",
            title_candidates=[DetectedTitle(official_title="잘못된 단일작", source_tier="community", page_type="wiki")],
            primary_work=None,
            mentioned_works=[],
            comparison_target=None,
            recommendation_candidates=[],
            metadata={"detected_author": "개돌"},
            verification_result={},
        )
        self.assertEqual(result["topicality"], "adjacent_relevant")
        self.assertIn(result["subtype"], {"author_meta", "release_serialization_meta"})
        self.assertIsNone(result["official_title"])
        self.assertFalse(result["is_relevant"])
        self.assertIn("작가", result["reason"])

