    def test_strip_title_character_suffix_preserves_verified_alias_suffix(self):
        pipeline = _build_pipeline()
        full_title = "헌터갤러리의 국가권력급 기계공주"
        ctx = ConversationContext(
            post_id=11718096,
            post_data={
                "post_id": 11718096,
                "title": "말하는 거 보니까 기계공주 잘 읽을 거 같다 ← 뭔 뜻임 이게",
                "content_blocks": [{"type": "text", "text": "하??"}],
            },
            comments=["장빙이 식별코드 보니까 기계공주 완전 잘 어울릴 거 같애!"],
        )
        ctx.set_expert_output(
            ExpertType.GATEKEEPER,
            {"detected_entities": {"possible_characters": ["기계공주"]}},
        )
        ctx.set_expert_output(
            ExpertType.VERIFIER,
            {
                "verification_result": {
                    "grounding_check": {
                        "matched_alias": "기계공주",
                        "title_abbrev_mentioned": True,
                    },
                    "relation_judgment": {
                        "observed_aliases": ["기계공주"],
                    },
                }
            },
        )
        ctx.snippet_hints = {
            "abbreviation_hints": [
                {"abbrev": "기계공주", "full": full_title},
            ]
        }

        pipeline._has_official_title_evidence = lambda _ctx, cand: cand in {
            full_title,
            "헌터갤러리의 국가권력급",
        }
        pipeline._score_candidate_evidence_bucket = lambda _bucket: 17
        pipeline._get_candidate_evidence_bucket = lambda _ctx, _cand: {}
        pipeline._title_mentioned_in_post_context = lambda _ctx, cand: cand == full_title
        pipeline._title_anchor_lexical_overlap = lambda _ctx, cand: 0.9 if cand == full_title else 0.1

        stripped = pipeline._strip_title_character_suffix(full_title, ctx)

        self.assertEqual(stripped, full_title)

