    def test_comment_url_recommendation_preserved_as_adjacent_candidate(self):
        pipeline = _build_pipeline()
        detail_url = "https://novelpia.com/novel/50764"
        detail_title = "[TS?] 깨어나 보니 여자가 되어 있었다. 그런데 달려 있는."
        normalized_detail_title = "깨어나 보니 여자가 되어 있었다. 그런데 달려 있는."
        post = PostInput(
            post_id=11718049,
            title="후타 암타물을 보고싶구나..",
            author="ㅇㅇ",
            created_at="2026-01-28 18:32:00",
            content_blocks=[],
            comments=[detail_url],
        )
        ctx = ConversationContext(
            post_id=11718049,
            post_data=pipeline._post_to_dict(post),
            comments=[detail_url],
        )
        ctx.fetched_page_info = [
            {
                "url": detail_url,
                "structured_info": {
                    "title": detail_title,
                    "page_title": f"{detail_title} - 노벨피아",
                    "page_type": "novel_page",
                    "content_status": "active",
                },
                "text_preview": f"{detail_title} 프룻푸릇 후타나리 TS 러브코미디",
            }
        ]
        ctx.set_expert_output(
            ExpertType.GATEKEEPER,
            {
                "post_type": "image_post",
                "context_clues": {
                    "has_url_in_comments": True,
                    "is_recommendation_request": True,
                },
            },
        )
        ctx.set_expert_output(
            ExpertType.DISCOURSE,
            {
                "discourse_analysis": {
                    "primary_domain": "novel_literature",
                    "intent": "discuss_genre",
                    "target_kind": "genre",
                }
            },
        )
        ctx.set_expert_output(
            ExpertType.VERIFIER,
            {
                "verification_result": {
                    "is_relevant": False,
                    "grounding_check": {"anchor_found": "none"},
                    "rejection_reason": "댓글의 URL은 추천 답변으로 해석됨.",
                }
            },
        )
        ctx.set_expert_output(
            ExpertType.ARBITER,
            {
                "final_decision": {
                    "is_relevant": False,
                    "discussion_type": "noise",
                    "official_title": None,
                    "official_novel_title": None,
                },
                "metadata_synthesis": {},
            },
        )

        output = pipeline._context_to_output(ctx)
        identity = output.identity

        self.assertFalse(identity.is_relevant)
        self.assertIsNone(identity.novel_identity)
        self.assertEqual(identity.topicality, "adjacent_relevant")
        self.assertEqual(identity.subtype, "recommendation_request")
        self.assertEqual(identity.discussion_type, "recommendation")
        self.assertEqual(identity.title_resolution_state, "adjacent")
        self.assertFalse(identity.title_resolution_allowed)
        self.assertIsNotNone(identity.recommendation_candidates)
        self.assertEqual(identity.recommendation_candidates[0].official_title, normalized_detail_title)
        self.assertEqual(identity.recommendation_candidates[0].heretic_url, detail_url)
        self.assertIn(
            "comment_url_recommendation_candidate_preserved",
            identity.consistency_flags or [],
        )

