    def test_comment_url_answer_fetches_missing_detail_page_title(self):
        from tempfile import TemporaryDirectory

        detail_url = "https://novelpia.com/novel/362860"
        detail_title = "준우승 세 번 했더니 미소녀 됨"
        for complete in (True, False):
            with self.subTest(complete=complete), TemporaryDirectory() as directory:
                calls = []

                def fetch(url):
                    calls.append(url)
                    self.assertEqual(url, detail_url)
                    return {
                        "url": url,
                        "fetch_transport_provenance": {"requested_url": url, "final_url": url,
                            "method": "httpx", "status_code": 200, "redirected": False},
                        "structured_info": {
                            "title": detail_title if complete else "",
                            "page_title": f"{detail_title} - 노벨피아" if complete else "노벨피아",
                            "page_type": "novel_page" if complete else "unknown",
                            "content_status": "active" if complete else "unknown",
                        },
                        "text": f"{detail_title} 알레미카 #TS #인터넷방송" if complete else "",
                    }

                pipeline = AgenticPipeline(llm=DummyLLM(), mcp=SimpleNamespace(fetch=fetch),
                    output_dir=Path(directory), max_iterations=2)
                # 로컬 fetch fixture를 실제 호출한다. 전역 offline 정책/외부 전송은 바꾸지 않는다.
                pipeline.enable_heretic_live_fetch = True
                pipeline.enable_url_fetch_disk_cache = True
                pipeline._llm_check_page_alive = lambda *_args, **_kwargs: None
                self.assertEqual(list(pipeline.url_fetch_cache_dir.iterdir()), [])
                self.assertEqual(pipeline._url_fetch_cache, {})
                comments = ["아빠가 내 육수임", "제목이", detail_url]
                ctx = ConversationContext(post_id=11695639,
                    post_data={"post_id": 11695639,
                        "title": "TS해서 인방하는데 아빠가 내 방송을 봄", "content_blocks": [],
                        "comments_raw": [{"author": f"ㅇㅇ{i}", "content": value}
                            for i, value in enumerate(comments)]}, comments=comments)
                ctx.set_expert_output(ExpertType.GATEKEEPER,
                    {"post_type": "work_discussion", "context_clues": {"has_url_in_comments": True}})
                title, url = pipeline._pick_comment_url_answered_specific_work(
                    ctx=ctx, verification_result={"grounding_check": {"anchor_found": "comment_url"}},
                )
                if complete:
                    self.assertEqual(title, detail_title)
                    self.assertEqual(url, detail_url)
                else:
                    self.assertIsNone(title)
                    self.assertIsNone(url)
                self.assertEqual(calls, [detail_url])
                self.assertTrue(ctx.fetched_page_info)
                observed = ctx.fetched_page_info[0]
                self.assertEqual(observed["url"], detail_url)
                self.assertEqual(observed["final_url"], detail_url)
                self.assertEqual(observed["structured_info"]["title"], detail_title if complete else "")
                self.assertEqual(observed["fetch_transport_provenance"]["status_code"], 200)

