    def test_multi_work_bundle_extracts_numbered_titles_into_mentions(self):
        pipeline = _build_pipeline()
        post = PostInput(
            post_id=206,
            title="9작품 하차 리뷰(노벨피아편)",
            author="ㅇㅇ",
            created_at="2026-01-28 18:41:00",
            content_blocks=[
                ContentBlock(type="text", text="1.회귀자의 갓겜 제작법하차당한 소설후반부에 VR게임 만든다고 했을때 개노잼이였음"),
                ContentBlock(type="text", text="2. 6성 가챠 캐릭터가 되었다"),
                ContentBlock(type="text", text="3. 게임업계 정상화"),
                ContentBlock(type="text", text="4. 절대 엘드미아 에가를 건드리지 마라"),
            ],
            comments=[],
        )
        ctx = ConversationContext(post_id=206, post_data=pipeline._post_to_dict(post), comments=[])
        title_candidates = [
            DetectedTitle(official_title="절대 엘드미아 에가를 건드리지 마라", confidence="High", source_tier="official_detail")
        ]

        final_candidates, primary_work, mentioned_works, _future_watch = pipeline._annotate_work_references(
            ctx=ctx,
            title_candidates=title_candidates,
            official_title="절대 엘드미아 에가를 건드리지 마라",
        )

        mentioned_titles = {mw.official_title for mw in mentioned_works}
        candidate_roles = {cand.official_title: cand.reference_role for cand in final_candidates}

        self.assertIsNotNone(primary_work)
