    def test_repeated_syllable_alias_prefers_canonical_work_over_community_review_headline(self):
        pipeline = _build_pipeline()
        post = PostInput(
            post_id=208,
            title="마좋좋좋 결말이 왜이러냐..",
            author="멜츠",
            created_at="2026-01-28 18:45:12",
            content_blocks=[ContentBlock(type="text", text="ts난교 뭐다이..")],
            comments=["저예요", "그것이 [사랑]", "미친년임"],
        )
        ctx = ConversationContext(post_id=208, post_data=pipeline._post_to_dict(post), comments=post.comments)
        ctx.search_results = [
            {
                "title": "웹소설로 꿈꾸는 세상! - 마법 좋아좋아좋아 - 노벨피아",
                "url": "https://novelpia.com/novel/326040",
            },
            {
                "title": "마법 좋아, 마법과 좋아 - 마좋좋좋 리뷰 - 장르소설 채널 - 아카라이브",
                "url": "https://arca.live/b/novelchannel/158302516",
            },
        ]
        ctx.suspected_titles = [{"title": "마법 좋아좋아좋아", "confidence": "High", "score": 0.9}]
        ctx.set_expert_output(
            ExpertType.VERIFIER,
            {
                "slang_insight": {
                    "detected_term": "마좋좋",
                    "decoded_term": "마법 좋아, 마법과 좋아",
                    "cultural_context": "약칭",
                },
                "grounding_check": {"anchor_found": "title_mention"},
            },
        )

        final_candidates, primary_work, mentioned_works, _ = pipeline._annotate_work_references(
            ctx=ctx,
            title_candidates=[
                DetectedTitle(
                    official_title="마법 좋아, 마법과 좋아",
                    alias_or_mention="마좋좋",
                    confidence="High",
                    source_tier="official_detail",
                ),
                DetectedTitle(
                    official_title="마좋좋좋 결말이 왜이러냐..",
                    alias_or_mention="마좋좋결말이왜이러냐..",
                    confidence="High",
                    source_tier="llm_only",
                ),
            ],
            official_title=None,
        )

        self.assertIsNotNone(primary_work)
        self.assertEqual(primary_work.official_title, "마법 좋아좋아좋아")
        self.assertEqual(primary_work.heretic_url, "https://novelpia.com/novel/326040")
        self.assertEqual(mentioned_works, [])

        by_title = {cand.official_title: cand for cand in final_candidates}
        self.assertIn("마법 좋아, 마법과 좋아", by_title)
        # 선택 URL이 없는 모델 후보는 검색 headline만으로 출처 등급을 얻지 않는다.
        self.assertEqual(by_title["마법 좋아, 마법과 좋아"].source_tier, "llm_only")
        self.assertIsNone(by_title["마법 좋아, 마법과 좋아"].heretic_url)
        self.assertIn("candidate_source_missing_url", by_title["마법 좋아, 마법과 좋아"].negative_evidence or [])
        self.assertIn(
            "missing_official_url_for_official_detail",
            by_title["마법 좋아, 마법과 좋아"].negative_evidence or [],
        )

