    def test_reason_body_summary_preserves_image_ocr_order(self):
        pipeline = _build_pipeline()
        post = PostInput(
            post_id=2102,
            title="5시간 뒤면 랫따싶이 올까요?",
            author="ㅇㅇ",
            created_at="2026-01-28 18:39:00",
            content_blocks=[
                ContentBlock(type="image", url="https://example.com/1.jpg"),
                ContentBlock(type="ocr_text", text="[이미지 OCR] 김머루의 인간 사냥 / 직접 확인된 작품명: 김머루의 인간 사냥"),
                ContentBlock(type="image_summary", text="[이미지 요약] 은발 캐릭터가 뱀에게 감긴 장면 / 이미지 직접 근거 작품명: 김머루의 인간 사냥"),
                ContentBlock(type="text", text="5시간 뒤면 랫따싶이 올까요?"),
            ],
            comments=[],
        )
        ctx = ConversationContext(post_id=2102, post_data=pipeline._post_to_dict(post), comments=[])
        body_summary = pipeline._build_reason_body_summary(ctx, max_items=10)
        self.assertIn("[이미지 첨부]", body_summary)
        self.assertIn("[이미지 OCR] 김머루의 인간 사냥", body_summary)
        self.assertIn("[이미지 요약] 은발 캐릭터가 뱀에게 감긴 장면", body_summary)
        self.assertTrue(body_summary.index("[이미지 첨부]") < body_summary.index("[이미지 OCR]"))
        self.assertTrue(body_summary.index("[이미지 OCR]") < body_summary.index("[이미지 요약]"))
        self.assertTrue(body_summary.index("[이미지 요약]") < body_summary.index("5시간 뒤면 랫따싶이 올까요?"))

