    def test_image_grounding_note_softens_nonmatching_ocr_title(self):
        pipeline = _build_pipeline()
        ctx = ConversationContext(
            post_id=21022,
            post_data={
                "post_id": 21022,
                "vlm_enrichment_used": True,
                "image_enrichment": [
                    {
                        "explicit_work_title": "벌어먹을 혼생!",
                        "evidence_type": "cover_title",
                        "background_listing_only": False,
                    }
                ],
            },
            comments=[],
        )
        note = pipeline._build_image_grounding_note(ctx, official_title="빌어먹을 환생")
        # 원시 판독은 지우지 않되 제목/별칭/작품 사실에 권한을 부여하지 않는다.
        self.assertIn("[이미지 OCR 진단·비권한 인용]", note)
        self.assertIn("벌어먹을 혼생!", note)
        self.assertIn("작품 사실·별칭 관계·공식 제목/URL 근거를 부여하지 않습니다", note)
        self.assertIn("최종 공개는 별도의 원문 관계와 공식쌍 계약에 따릅니다", note)
        self.assertEqual(ctx.post_data["image_enrichment"][0]["explicit_work_title"], "벌어먹을 혼생!")
        self.assertNotIn("직접 근거(OCR/표지)에서도", note)

