    def test_slang_context_neutralizes_nonmatching_ocr_as_image_candidate(self):
        from llm_batch.domain.models import PickvelAnalysis, SlangInsight

        pipeline = _build_pipeline()
        ctx = ConversationContext(
            post_id=21023,
            post_data={
                "post_id": 21023,
                "title": "빌환 표지변경됨",
                "vlm_enrichment_used": True,
                "image_enrichment": [
                    {
                        "explicit_work_title": "불먹을 혼성명",
                        "evidence_type": "cover_title",
                        "background_listing_only": False,
                    }
                ],
            },
            comments=[],
        )

        text = pipeline._sanitize_slang_cultural_context_for_image_conflict(
            "제목 '빌환'은 '빌어먹을 환생'의 약칭이다. "
            "본문에는 '불먹을 혼성명'이라는 다른 제목이 병기되어 있으나, "
            "본문 이미지 OCR 내용 ('불먹을 혼성명', '국마 퓨전판타지 소설')은 "
            "해당 작품의 설정이나 2차 창작물 관련 단서로 해석되었으나, "
            "검색 결과 및 플랫폼 URL을 통해 '빌어먹을 환생'이 정식 작품으로 확인됨.",
            ctx=ctx,
            official_title="빌어먹을 환생",
        )

        # 조기 helper는 공개쌍 이전의 자유 설명을 유예한다. 최종 source 경계에서 검산한다.
        self.assertIn("설정이나 2차 창작물 관련 단서", text)
        identity = PickvelIdentity(
            is_relevant=False, discussion_type="general",
            slang_insight=SlangInsight(
                detected_term="빌환", decoded_term=None, decode_verified=False,
                cultural_context=text, alias_scope="mixed_unknown", store_in_slang_db=False,
            ),
        )
        notes, _native_verify = pipeline._consume_final_source_context(ctx, identity, None)
        analysis = PickvelAnalysis(notes=notes)
        pipeline._apply_ocr_reader_provenance_before_source_seal(ctx, identity, analysis)
        final_text = identity.slang_insight.cultural_context
        self.assertIsInstance(final_text, str)
        self.assertIn("빌환 표지변경됨", final_text)
        self.assertNotIn("본문에는 '불먹을 혼성명'", final_text)
        self.assertNotIn("설정이나 2차 창작물 관련 단서", final_text)
        self.assertTrue(pipeline._verify_final_source_reader_fields(ctx, identity, analysis))
        self.assertIsNone(identity.novel_identity)
        self.assertFalse(identity.slang_insight.store_in_slang_db)

    def test_analysis_notes_neutralizes_conflict_ocr_alias_claim(self):
        pipeline = _build_pipeline()
        ctx = ConversationContext(
            post_id=21023,
            post_data={
                "post_id": 21023,
                "title": "빌환 표지변경됨",
                "vlm_enrichment_used": True,
                "image_enrichment": [
                    {
                        "explicit_work_title": "불먹을 혼성명",
                        "evidence_type": "cover_title",
                        "background_listing_only": False,
                    }
                ],
            },
            comments=[],
        )

        notes = pipeline._sanitize_analysis_notes(
            ctx=ctx,
            notes=(
                "[Synthesizer] 본 포스트는 '빌어먹을 환생'이라는 웹소설의 표지 변경에 관한 내용이다. "
                "'빌환', '불먹' 등은 모두 이 작품의 공식/비공식 별칭으로 확인된다."
            ),
            reason="이미지 OCR/표지 후보가 최종 제목과 일치하지 않아 보조 제목 근거로 사용하지 않습니다: 불먹을 혼성명.",
            is_relevant=True,
            official_title="빌어먹을 환생",
            heretic_url="https://novel.munpia.com/222360",
            discussion_type="character_talk",
            topicality="core_relevant",
            work_resolution="resolved",
        )

        # 최종 reason으로 중립화된 설명도 OCR를 별칭/공식 제목의 근거로 만들지 않는다.
        self.assertIn("이미지 OCR/표지 후보", notes)
        self.assertIn("최종 제목과 일치하지 않아", notes)
        self.assertIn("보조 제목 근거로 사용하지 않습니다", notes)
        self.assertIn("불먹을 혼성명", notes)
        self.assertNotIn("불먹' 등은 모두", notes)
        self.assertNotIn("공식/비공식 별칭으로 확인", notes)

