    def test_topic_particle_lexical_alias_is_preserved_without_public_promotion(self):
        import copy

        pipeline = _build_pipeline()
        pipeline.enable_url_fetch_disk_cache = False
        pipeline.mcp.fetch = lambda _url: None
        post = PostInput(
            post_id=11718097,
            title="망겜힐은 오행복 박태양이 빌런이어야돼",
            author="ㅇㅇ",
            content_blocks=[
                ContentBlock(type="text", text="박태양과 ts녀, 족장님 관련 전개를 비평함")
            ],
            comments=[],
        )
        ctx = ConversationContext(post_id=11718097, post_data=pipeline._post_to_dict(post), comments=[])
        ctx.search_results = [
            {
                "title": "망겜의 힐러 - 네이버 시리즈",
                "url": "https://series.naver.com/novel/detail.series?productNo=7774",
                "content": "망겜의 힐러 웹소설 작품 페이지. 장르 판타지. 작가 검미성.",
                "query": "망겜힐 웹소설",
            }
        ]

        before_post = copy.deepcopy(ctx.post_data)
        before_search = copy.deepcopy(ctx.search_results)
        self.assertEqual(pipeline._extract_post_title_lead_alias_terms(ctx)[0], "망겜힐")
        hit = pipeline._infer_alias_title_from_search_evidence(ctx, "망겜힐")
        self.assertIsNotNone(hit)
        self.assertEqual(hit["alias"], "망겜힐")
        self.assertEqual(hit["title"], "망겜의 힐러")
        candidate, batch_hit = pipeline._resolve_batch_memory_alias_candidate(ctx, {})
        self.assertIsNone(candidate)
        self.assertIsNone(batch_hit)
        # 검색의 lexical 후보는 남지만 현재 원문의 역할 근거로는 승격하지 않는다.
        self.assertEqual(ctx._batch_alias_rescue_blocked_nonwork_context_reason, "genre_discussion_nonwork_context")
        held = pipeline._collect_blocked_batch_alias_hold_candidates(ctx)
        self.assertEqual(len(held), 1)
        self.assertEqual(held[0].official_title, "망겜의 힐러")
        self.assertEqual(held[0].alias_or_mention, "망겜힐")
        self.assertEqual(held[0].heretic_url, "https://series.naver.com/novel/detail.series?productNo=7774")
        self.assertEqual(held[0].confidence, "Medium")
        self.assertIsNot(held[0].locked, True)
        self.assertEqual(held[0].reference_role, "candidate")
        self.assertIn("batch_alias_nonwork_context_hold_without_promotion", held[0].negative_evidence or [])

        # 실제 보존 병합과 snapshot을 재사용한다. 새 권한이나 가짜 source를 주입하지 않는다.
        extended = {}
        recommendations = pipeline._merge_local_candidate_preservation_hints(
            ctx=ctx, discussion_type=None, recommendation_candidates=[],
            extended_identity=extended, official_title=None)
        snapshot = pipeline._build_candidate_preservation_snapshot(
            title_candidates=[], mentioned_works=[], comparison_target=None,
            recommendation_candidates=recommendations,
            local_diagnostic_sources=extended.get("_local_surface_diagnostic_holds"))
        retained = list(snapshot.retained_sources)
        self.assertTrue(any(item.get("official_title") == "망겜의 힐러"
            and item.get("alias_or_mention") == "망겜힐" for item in retained))
        for item in retained:
            if item.get("official_title") == "망겜의 힐러":
                self.assertEqual(item.get("reference_role"), "candidate")
                self.assertEqual(item.get("confidence"), "Medium")
                self.assertEqual(item.get("promotion_policy"), "hold_without_promotion")

        # 실제 공개 계약은 후보 inventory만으로 대표 title/URL을 선택하지 않는다.
        from llm_batch.promotion_gate import (
            GroundingState, candidate_inventory_evidence_from_sources, evaluate_publish_contract)
        evidence = candidate_inventory_evidence_from_sources(retained)
        self.assertTrue(evidence)
        self.assertFalse(any(item.supports_publish for item in evidence))
        contract = evaluate_publish_contract(GroundingState(
            post_id=ctx.post_id, candidate_title="", candidate_url="",
            candidate_inventory_count=len(retained)), evidence)
        self.assertEqual(contract.decision.status, "candidate_only")
        self.assertIs(contract.decision.publish_allowed, False)
        self.assertIs(contract.decision.bypassed_gate, False)
        self.assertIs(contract.decision.candidate_preserved, True)
        self.assertIsNone(contract.decision.official_title)
        self.assertIsNone(contract.decision.official_url)
        self.assertEqual(ctx.post_data, before_post)
        self.assertEqual(ctx.search_results, before_search)

        # 이전 ctx의 거절 진단을 재사용하지 않는 별도 원문에 검색 근거가 없으면 후보도 없다.
        empty_ctx = ConversationContext(post_id=post.post_id,
            post_data=pipeline._post_to_dict(post), comments=[])
        self.assertEqual(pipeline._resolve_batch_memory_alias_candidate(empty_ctx, {}), (None, None))
        self.assertEqual(pipeline._collect_blocked_batch_alias_hold_candidates(empty_ctx), [])

