    def test_image_only_ocr_title_seed_is_pruned_when_stable_alias_exists(self):
        orch = Orchestrator(experts={}, search_fn=lambda *_args, **_kwargs: [], fetch_fn=None)
        ctx = ConversationContext(
            post_id=30225,
            post_data={
                "post_id": 30225,
                "title": "빌환 표지변경됨",
                "normalized_title": "빌환 표지변경됨",
                "content_blocks": [
                    {"type": "ocr_text", "text": "[이미지 OCR] MUNPIA 벌어먹을 혼생! 목마 퓨전판타지 소설"},
                    {"type": "image_summary", "text": "[이미지 요약] 판타지 웹소설 표지"},
                    {"type": "text", "text": "시엘이랑 세냐 빼고 아니스티나랑 매르만 있어도 된다는 말은 ㄴㄴ"},
                ],
                "image_enrichment": [
                    {
                        "screen_type": "work_surface",
                        "focus_role": "work_anchor",
                        "promotion_eligible": True,
                        "ocr_text": "MUNPIA 벌어먹을 혼생! 목마 퓨전판타지 소설",
                        "explicit_work_title": "벌어먹을 혼생!",
                        "visual_summary": "판타지 웹소설 표지",
                    }
                ],
            },
            comments=[],
        )
        gatekeeper_result = {
            "detected_entities": {
                "possible_titles": ["빌환", "벌어먹을 혼생!"],
                "possible_characters": ["시엘", "세냐", "아니스티나", "매르"],
                "possible_authors": [],
            },
            "context_clues": {"short_post_fast_path": True},
        }
        search_requests = [
            {"query": "빌환 웹소설", "purpose": "title_search_community", "priority": 1},
            {"query": "벌어먹을 혼생! 웹소설", "purpose": "title_search_community", "priority": 1},
            {"query": "(site:novelpia.com OR site:munpia.com OR site:series.naver.com) 벌어먹을 혼생!", "purpose": "official_title_verify", "priority": 1},
            {"query": "벌어먹을 혼생! 시엘 웹소설", "purpose": "alias_bridge_search", "priority": 1},
            {"query": "벌어먹을 혼생! 빌어먹을 환생", "purpose": "decoder_recall_verification", "priority": 1},
            {"query": "벌어먹을 혼생! 시엘", "purpose": "abbreviation_verification", "priority": 1},
            {"query": "빌어먹을 환생 웹소설", "purpose": "known_abbr_fullname_search", "priority": 0},
        ]

        pruned = orch._prune_image_only_title_seed_search_requests(
            ctx,
            search_requests,
            gatekeeper_result=gatekeeper_result,
            phase="test",
        )

        queries = [item["query"] for item in pruned]
        self.assertIn("빌환 웹소설", queries)
        self.assertIn("빌어먹을 환생 웹소설", queries)
        self.assertNotIn("벌어먹을 혼생! 웹소설", queries)
        self.assertFalse(any("벌어먹을 혼생!" in q for q in queries))

