    def test_image_only_ocr_missing_typed_evidence_cannot_seed_search(self):
        orch = Orchestrator(experts={}, search_fn=lambda *_args, **_kwargs: [], fetch_fn=None)
        ctx = ConversationContext(
            post_id=30226,
            post_data={
                "post_id": 30226,
                "title": "이거 뭐임",
                "normalized_title": "이거 뭐임",
                "content_blocks": [
                    {"type": "ocr_text", "text": "[이미지 OCR] 김머루의 인간 사냥"},
                    {"type": "image_summary", "text": "[이미지 요약] 웹소설 표지"},
                ],
                "image_enrichment": [
                    {
                        "screen_type": "work_surface",
                        "focus_role": "work_anchor",
                        "promotion_eligible": True,
                        "ocr_text": "김머루의 인간 사냥",
                        "explicit_work_title": "김머루의 인간 사냥",
                    }
                ],
            },
            comments=[],
        )
        gatekeeper_result = {
            "detected_entities": {
                "possible_titles": ["김머루의 인간 사냥"],
                "possible_characters": [],
                "possible_authors": [],
            },
            "context_clues": {},
        }
        search_requests = [
            {"query": "김머루의 인간 사냥 웹소설", "purpose": "title_search_community", "priority": 1},
            {"query": "(site:novelpia.com OR site:munpia.com OR site:series.naver.com) 김머루의 인간 사냥", "purpose": "official_title_verify", "priority": 1},
        ]

        # promotion_eligible 하나로 빠진 근거 종류/제목 역할을 보충하지 않는다.
        image_before = dict(ctx.post_data["image_enrichment"][0])
        requests_before = [dict(request) for request in search_requests]
        self.assertNotIn("evidence_type", image_before)
        self.assertNotIn("title_role", image_before)
        self.assertEqual(orch._protected_promotable_image_anchor_norms(ctx), (set(), set()))
        pruned = orch._prune_image_only_title_seed_search_requests(
            ctx,
            search_requests,
            gatekeeper_result=gatekeeper_result,
            phase="test",
        )

        self.assertEqual(pruned, [])
        self.assertEqual(search_requests, requests_before)
        self.assertEqual(ctx.post_data["image_enrichment"][0], image_before)
        self.assertEqual(image_before["explicit_work_title"], "김머루의 인간 사냥")
        self.assertTrue(image_before["promotion_eligible"])

