    def test_character_parenthetical_wiki_hint_registers_work_bridge(self):
        orch = Orchestrator(experts={}, search_fn=lambda *_args, **_kwargs: [], fetch_fn=None)
        ctx = ConversationContext(
            post_id=11663540,
            post_data={
                "post_id": 11663540,
                "title": "TS) 주서연 전차랑 줄다리기 하면 이길까?",
                "content_blocks": [{"type": "text", "text": "내가 봤을땐 이 고릴라년이 가볍게 이길것 같은데"}],
            },
            comments=["전차 주제에 주서연이랑 비비려하네"],
        )
        hints = orch._extract_hints_from_snippets(
            [
                {
                    "title": "주서연(전 버튜버가 하고 싶은데요) - 나무위키",
                    "content": "전생엔 겨우 취업에 성공한 성인 남성이었으나...",
                    "url": "https://namu.wiki/w/%EC%A3%BC%EC%84%9C%EC%97%B0(%EC%A0%84%20%EB%B2%84%ED%8A%9C%EB%B2%84%EA%B0%80%20%ED%95%98%EA%B3%A0%20%EC%8B%B6%EC%9D%80%EB%8D%B0%EC%9A%94)",
                }
            ],
            ["주서연"],
        )

        orch._merge_snippet_hints(ctx, hints, ["주서연"], post_data=ctx.post_data)

        self.assertTrue(
            any(
                h.get("title") == "전 버튜버가 하고 싶은데요"
                and h.get("source") == "character_parenthetical_wiki"
                for h in ctx.snippet_hints.get("title_hints", [])
            )
        )
        self.assertTrue(
            any(
                v.get("character") == "주서연"
                and v.get("title") == "전 버튜버가 하고 싶은데요"
                for v in getattr(ctx, "verified_character_work_links", [])
            )
        )
        self.assertTrue(
            any(
                st.get("title") == "전 버튜버가 하고 싶은데요"
                and st.get("source_expert") == "character_parenthetical"
                for st in ctx.suspected_titles
            )
        )

