    def test_vlm_logs_chunk_details_immediately(self):
        class _Resp:
            def __init__(self, body: bytes, content_type: str = "image/png") -> None:
                self.content = body
                self.headers = {"content-type": content_type}

            def raise_for_status(self) -> None:
                return None

        fake_llm = FakeMultimodalLLM()
        with patch.dict(
            "os.environ",
            {
                "LLM_VLM": "1",
                "LLM_OCR": "1",
                "LLM_VLM_MAX_IMAGE_BYTES": "4096",
                "LLM_VLM_MAX_TOTAL_BYTES": "4096",
                "LLM_VLM_CHUNK_MAX_IMAGES": "8",
                "LLM_VLM_CHUNK_MAX_BYTES": "4096",
            },
            clear=False,
        ):
            pipeline = AgenticPipeline(llm=fake_llm, mcp=DummyMCP(), max_iterations=2)
            post = PostInput(
                post_id=4021,
                title="표지 OCR 확인",
                url="https://gall.dcinside.com/mgallery/board/view/?id=genrenovel&no=4021",
                content_blocks=[ContentBlock(type="image", url="https://dcimg1.dcinside.com/1.png")],
                comments=[{"content": "표지 떴네"}],
            )
            post_dict = pipeline._post_to_dict(post)
            stderr = io.StringIO()
            with (
                patch("llm_batch.agentic_pipeline.httpx.get", return_value=_Resp(b"12345678")),
                redirect_stderr(stderr),
            ):
                enriched = pipeline._maybe_enrich_post_images(post_dict=post_dict, comments=["표지 떴네"])

        log_output = stderr.getvalue()
        self.assertTrue(enriched["vlm_enrichment_used"])
        self.assertIn("🖼️ VLM chunk result: post_id=4021 chunk=1/1", log_output)
        self.assertIn("img#1", log_output)
        self.assertIn("title=작품1", log_output)
        self.assertIn("author=작가A", log_output)
        self.assertIn("OCR: OCR 1", log_output)
        self.assertIn("SUMMARY: 요약 1", log_output)
        self.assertIn("CUES: 단서1", log_output)
        self.assertIn("🖼️ VLM merged evidence: post_id=4021 images=1", log_output)

