        fake_llm = FakeWeakThenOcrLLM()
        with patch.dict(
            "os.environ",
            {
                "LLM_VLM": "1",
                "LLM_OCR": "1",
                "LLM_VLM_MAX_IMAGE_BYTES": "4096",
                "LLM_VLM_MAX_TOTAL_BYTES": "4096",
            },
            clear=False,
        ):
            pipeline = AgenticPipeline(llm=fake_llm, mcp=DummyMCP(), max_iterations=2)
            post = PostInput(
                post_id=11716480,
                title="아오 포티햄",
                url="https://gall.dcinside.com/mgallery/board/view/?id=genrenovel&no=11716480",
                content_blocks=[ContentBlock(type="image", url="https://dcimg1.dcinside.com/ocr_retry.png")],
                comments=[],
            )
            post_dict = pipeline._post_to_dict(post)
            stderr = io.StringIO()
            with (
                patch("llm_batch.agentic_pipeline.httpx.get", return_value=_Resp(b"12345678")),
                redirect_stderr(stderr),
            ):
                enriched = pipeline._maybe_enrich_post_images(post_dict=post_dict, comments=[])

        self.assertEqual(len(fake_llm.calls), 2)
        self.assertTrue(fake_llm.calls[1]["kwargs"]["tag"].startswith("vlm_ocr_retry_post_11716480"))
        self.assertIn("텍스트 전용 재시도", fake_llm.calls[1]["user_text"])
        self.assertEqual(enriched["vlm_ocr_retry_count"], 1)
        self.assertIn("vlm_ocr_retry_recovered", enriched["image_enrichment_limitations"])
        self.assertTrue(enriched["vlm_enrichment_used"])
