        self.assertEqual(enriched["image_enrichment"][0]["screen_type"], "work_surface")
        self.assertTrue(enriched["image_enrichment"][0]["promotion_eligible"])
        block_types = [str((blk or {}).get("type") or "") for blk in enriched["content_blocks"]]
        self.assertIn("ocr_text", block_types)
        self.assertIn("image_summary", block_types)
        log_output = stderr.getvalue()
        self.assertIn("VLM OCR retry request", log_output)
        self.assertIn("direct_titles: 여대생 가랑이 사이 무릎 꿇은 엄마들", log_output)

