    def test_non_image_recommendation_survives_cross_media_vlm_attachment(self):
        pipeline = _build_pipeline()
        post = PostInput(
            post_id=11718087,
            title="노벨피아 성인 백합소설 추천좀",
            content_blocks=[
                ContentBlock(type="image", url="https://dcimg.example/card.jpg"),
                ContentBlock(type="image_summary", text="[이미지 요약] 카드 게임(TCG)의 몬스터 카드 이미지입니다."),
            ],
            comments=["ts잘먹음"],
        )
        post_dict = pipeline._post_to_dict(post)
        post_dict["vlm_enrichment_used"] = True
        post_dict["image_enrichment"] = [
            {
                "visual_summary": "카드 게임(TCG)의 몬스터 카드 이미지입니다.",
                "ocr_text": "심연에 숨은 자 / 몬스터 카드 / ATK 1700",
                "screen_type": "text_surface",
                "focus_role": "supporting_text",
                "promotion_eligible": False,
                "explicit_work_title": "",
                "explicit_author_name": "",
            }
        ]
        ctx = ConversationContext(post_id=11718087, post_data=post_dict, comments=["ts잘먹음"])
        ctx.set_expert_output(
            ExpertType.DISCOURSE,
            {
                "discourse_analysis": {
                    "primary_domain": "gaming",
                    "domain_confidence": "high",
                    "intent": "recommendation_request",
                    "target_kind": "genre",
                }
            },
        )

        taxonomy = pipeline._derive_output_taxonomy(
            ctx=ctx,
            is_relevant=False,
            discussion_type="off_topic",
            official_title=None,
            title_candidates=[],
            primary_work=None,
            mentioned_works=[],
            comparison_target=None,
            recommendation_candidates=[],
            metadata={},
            verification_result={
                "grounding_check": {"anchor_found": "none"},
                "rejection_reason": "첨부 이미지는 카드 게임 스크린샷이다.",
            },
        )

        self.assertEqual(taxonomy["topicality"], "adjacent_relevant")
        self.assertEqual(taxonomy["subtype"], "recommendation_request")
        self.assertEqual(taxonomy["work_resolution"], "none")

        result = pipeline._apply_output_consistency_validator(
            ctx=ctx,
            is_relevant=False,
            discussion_type="off_topic",
            official_title=None,
            confidence="Medium",
            reason="게임 카드 이미지라 특정 작품으로 확정하지 않음",
            notes="게임 카드 이미지라 특정 작품으로 확정하지 않음",
            title_candidates=[
                DetectedTitle(
                    official_title="성인용품점에 백합이 피었습니다",
                    heretic_url="https://novelpia.com/novel/12345",
                    confidence="Medium",
                    source_tier="official_detail",
                )
            ],
            primary_work=None,
            mentioned_works=[],
            comparison_target=None,
            recommendation_candidates=[],
            metadata={},
            verification_result={
                "grounding_check": {"anchor_found": "none"},
                "relation_judgment": {
                    "relation_type": "genre_or_trope_label",
                    "discussion_target": "genre_general",
                    "promotion_decision": "reject",
                },
                "counter_arguments": [
                    {
                        "severity": "major",
                        "issue": "본문 이미지는 TCG 카드라 후보 작품과 직접 연결되지 않음",
                    }
                ],
            },
        )

        self.assertFalse(result["is_relevant"])
        self.assertIsNone(result["official_title"])
        self.assertEqual(result["topicality"], "adjacent_relevant")
        self.assertEqual(result["subtype"], "recommendation_request")
        self.assertEqual(result["discussion_type"], "recommendation")
        self.assertIn("generic_relation_recommendation_preserved", result["consistency_flags"])

