    def test_gatekeeper_prunes_speculative_alias_expansion_title(self):
        gatekeeper = GatekeeperExpert(llm_client=DummyLLM())
        result = {
            "is_noise": False,
            "post_type": "work_discussion",
            "detected_entities": {
                "possible_titles": ["괴담텔", "괴담 텔레파시"],
                "possible_authors": [],
                "possible_characters": ["미로"],
            },
            "key_terms": ["괴담텔", "미로", "알레프"],
            "context_clues": {},
        }
        post = {
            "title": "괴담텔 미로 진짜 존나 슈퍼스타네ㅋㅋㅋ",
            "content_blocks": [
                {"type": "text", "text": "305호 죄수 반지로 위대한 자 되고 미로 죽일려고함"},
                {"type": "text", "text": "근데 미로가 사실 반지를 최초로 깨운 주인이고 원흉이었다"},
            ],
        }

        out = gatekeeper._prune_speculative_alias_expansions(result, post)
