    def test_gatekeeper_keeps_comment_title_candidate_details_without_forced_merge(self):
        gatekeeper = GatekeeperExpert(llm_client=DummyLLM())
        result = {
            "is_noise": False,
            "detected_entities": {
                "possible_titles": [],
                "possible_authors": [],
                "possible_characters": [],
            },
            "context_clues": {},
        }
        post = {
            "comments_raw": [
                {
                    "author": "ㅇㅇ",
                    "content": "@세카이데\n칼취밤",
                    "reply_to_comment_id": "c1",
                    "reply_level": 1,
                }
            ]
        }

        out = gatekeeper._postprocess_comment_titles(result, post, ["@세카이데\n칼취밤"])
        clues = out.get("context_clues") or {}

        self.assertIn("칼취밤", clues.get("comment_title_candidates") or [])
        self.assertEqual(clues.get("comment_title_merge_candidates") or [], [])
        details = clues.get("comment_title_candidate_details") or []
        self.assertTrue(details)
        self.assertTrue(details[0].get("has_at_mention"))

    def test_pipeline_preserves_comment_author_ip_context_separately_from_text(self):
        pipeline = _build_pipeline()
        post = PostInput(
            post_id=7001,
            title="댓글로 찾은 작품",
            author="글쓴이",
            content_blocks=[ContentBlock(type="text", text="이거 제목 뭐였지")],
            comments=[
                {
                    "comment_id": "c1",
                    "author": "글쓴이",
                    "ip": "123.248",
                    "content": "아 이거 맞다",
                    "reply_level": 0,
                    "reply_to_comment_id": None,
                },
                {
                    "comment_id": "c2",
                    "author": "다른유저",
                    "ip": "211.36",
                    "content": "작품명 후보",
                    "reply_level": 1,
                    "reply_to_comment_id": "c1",
                },
            ],
        )

        post_dict = pipeline._post_to_dict(post)
        comments = pipeline._extract_comments(post)

        self.assertEqual(post_dict.get("gallery_id"), "test")
        self.assertEqual(post_dict.get("post_author"), post.author)

        self.assertEqual(comments, ["아 이거 맞다", "작품명 후보"])
        meta = post_dict.get("comment_metadata") or []
        self.assertEqual(len(meta), 2)
        self.assertEqual(meta[0].get("gallery_id"), "test")
        # 표시명 일치와 인증된 작성자 관계를 구분하고 원문 메타데이터를 보존한다.
        self.assertFalse(meta[0]["is_post_author"])
        self.assertTrue(meta[0]["post_author_match_unverified"])
        self.assertEqual(meta[0]["speaker"], "user1")
        self.assertFalse(meta[1]["is_post_author"])
        self.assertFalse(meta[1]["post_author_match_unverified"])
        self.assertEqual(meta[1]["speaker"], "user2")
        self.assertEqual([m["author"] for m in meta], ["글쓴이", "다른유저"])
        self.assertEqual([m["ip"] for m in meta], ["123.248", "211.36"])
        self.assertEqual([m["comment_id"] for m in meta], ["c1", "c2"])
        self.assertEqual([m["content_preview"] for m in meta], comments)
        self.assertEqual(meta[1]["reply_to_comment_id"], "c1")
        self.assertEqual(meta[1]["reply_level"], 1)
        self.assertIn("author=글쓴이", post_dict.get("comment_context_lines", [])[0])
        self.assertIn("role=author_match_unverified", post_dict.get("comment_context_lines", [])[0])
        self.assertNotIn("role=post_author", post_dict.get("comment_context_lines", [])[0])
        self.assertIn("author=다른유저", post_dict.get("comment_context_lines", [])[1])
        self.assertIn("reply_to=c1", post_dict.get("comment_context_lines", [])[1])
        dialogue_lines = post_dict.get("comment_dialogue_context_lines", [])
        self.assertIn("role=author_match_unverified", dialogue_lines[0])
        self.assertNotIn("role=post_author", dialogue_lines[0])
        self.assertIn("text=아 이거 맞다", dialogue_lines[0])
        self.assertIn("author=다른유저", dialogue_lines[1])
        self.assertIn("text=작품명 후보", dialogue_lines[1])

        gatekeeper = GatekeeperExpert(llm_client=DummyLLM())
        prompt_json = gatekeeper._build_post_json(post_dict, comments)
        self.assertIn("comment_context", prompt_json)
        self.assertIn("comment_dialogue_context", prompt_json)
        self.assertEqual(prompt_json.get("gallery_id"), "test")
        self.assertEqual(prompt_json.get("post_author"), post.author)
        self.assertEqual(prompt_json["comments"], comments)
        self.assertEqual(prompt_json["comment_context"], post_dict["comment_context_lines"])
        self.assertEqual(prompt_json["comment_dialogue_context"], dialogue_lines)

    def test_anonymous_comment_author_uses_ip_before_post_author_role(self):
        pipeline = _build_pipeline()
        post = PostInput(
            post_id=7002,
            title="익명 댓글 대화",
            author="ㅇㅇ",
            ip="123.248",
            content_blocks=[ContentBlock(type="text", text="댓글에 내가 정정함")],
            comments=[
                {
                    "comment_id": "c1",
                    "author": "ㅇㅇ",
                    "ip": "123.248",
                    "content": "아 이건 내가 쓴 추가 설명",
                    "reply_level": 0,
                },
                {
                    "comment_id": "c2",
                    "author": "ㅇㅇ",
                    "ip": "211.36",
                    "content": "다른 유동이 단 댓글",
                    "reply_level": 0,
                },
            ],
        )

        post_dict = pipeline._post_to_dict(post)
        self.assertEqual(post_dict.get("post_ip"), "123.248")
        meta = post_dict.get("comment_metadata") or []
        self.assertEqual(len(meta), 2)
        # 같은 익명 표시명은 두 댓글 모두 미인증 일치다. 다른 IP는 화자 라벨만 분리한다.
        self.assertFalse(meta[0]["is_post_author"])
        self.assertTrue(meta[0]["post_author_match_unverified"])
        self.assertEqual(meta[0]["speaker"], "user1")
        self.assertFalse(meta[1]["is_post_author"])
        self.assertTrue(meta[1]["post_author_match_unverified"])
        self.assertEqual(meta[1]["speaker"], "user2")
        self.assertEqual([m["author"] for m in meta], ["ㅇㅇ", "ㅇㅇ"])
        self.assertEqual([m["ip"] for m in meta], ["123.248", "211.36"])
        self.assertEqual([m["comment_id"] for m in meta], ["c1", "c2"])
        self.assertEqual([m["content_preview"] for m in meta], ["아 이건 내가 쓴 추가 설명", "다른 유동이 단 댓글"])
        self.assertEqual(pipeline._extract_comments(post), ["아 이건 내가 쓴 추가 설명", "다른 유동이 단 댓글"])
        self.assertEqual(post_dict.get("post_author"), "ㅇㅇ")
        self.assertIn("role=author_match_unverified", post_dict.get("comment_dialogue_context_lines", [])[0])
        self.assertIn("role=author_match_unverified", post_dict.get("comment_dialogue_context_lines", [])[1])
        self.assertNotIn("role=post_author", post_dict.get("comment_dialogue_context_lines", [])[0])
        self.assertNotIn("role=post_author", post_dict.get("comment_dialogue_context_lines", [])[1])

        ctx = ConversationContext(post_id=7002, post_data=post_dict, comments=pipeline._extract_comments(post))
        self.assertFalse(pipeline._has_only_post_author_comment_context(ctx))
        self.assertTrue(pipeline._has_only_post_author_or_unverified_same_author_comment_context(ctx))

