    def test_title_genericness_profile_detects_hashtag_only_trope_candidate(self):
        pipeline = _build_pipeline()
        post = PostInput(
            post_id=6001,
            title="와 이거 뭐냐",
            author="ㅇㅇ",
            created_at="2026-01-28 18:44:25",
            content_blocks=[
                ContentBlock(
                    type="text",
                    text="빙의한 엄마가 아들을 ... #현대 #TS #빙의 #패륜 #근친 #피카레스크 #정신붕괴",
                )
            ],
            comments=[],
        )
        ctx = ConversationContext(post_id=6001, post_data=pipeline._post_to_dict(post), comments=[])
        ctx.post_data["image_enrichment"] = [
            {
                "ocr_text": "빙의한 엄마가 아들을 ... #현대 #TS #빙의 #패륜 #근친 #피카레스크",
                "explicit_work_title": "빙의한 엄마가 아들을 유혹함",
                "title_role": "work_title",
            }
        ]

        trope_profile = pipeline._compute_title_genericness_profile(ctx, "피카레스크")
        work_profile = pipeline._compute_title_genericness_profile(ctx, "빙의한 엄마가 아들을 유혹함")

        self.assertTrue(trope_profile.get("tag_like"))
        self.assertTrue(trope_profile.get("block_promotion"))
        self.assertGreater(
            int(trope_profile.get("genericness_score") or 0),
            int(work_profile.get("genericness_score") or 0),
        )

