    def test_verifier_failure_preserves_recommendation_request_as_unresolved(self):
        pipeline = _build_pipeline()
        post = PostInput(
            post_id=6001,
            title="마법도서관이 살아있다 무슨내용임?",
            author="ㅇㅇ",
            created_at="2026-01-28 18:44:25",
            content_blocks=[ContentBlock(type="text", text="하렘같은데 캐빨 좋음??")],
            comments=["대충 봉인된 주인공이 나오는 내용", "캐빨은 나름 괜찮음"],
        )
        ctx = ConversationContext(post_id=6001, post_data=pipeline._post_to_dict(post), comments=post.comments)
        ctx.set_expert_output(
            ExpertType.GATEKEEPER,
            {
                "post_type": "recommendation",
                "context_clues": {"is_recommendation_request": True},
                "detected_entities": {"possible_titles": [], "possible_authors": [], "possible_characters": []},
            },
        )
        ctx.set_expert_output(
            ExpertType.DISCOURSE,
            {
                "discourse_analysis": {
                    "primary_domain": "novel_literature",
                    "intent": "ask_question",
                    "is_association_not_discussion": False,
                }
            },
        )

        result = pipeline._apply_output_consistency_validator(
            ctx=ctx,
            is_relevant=False,
            discussion_type="noise",
            official_title=None,
            confidence="Low",
            reason="Verifier 검증 오류: name 're' is not defined",
            notes=None,
            title_candidates=[],
            primary_work=None,
            mentioned_works=[],
            comparison_target=None,
            recommendation_candidates=[],
            metadata={},
            verification_result={
                "verification_error": True,
                "rejection_reason": "Verifier 검증 오류: name 're' is not defined",
            },
        )

        self.assertTrue(result["is_relevant"])
        self.assertEqual(result["topicality"], "core_relevant")
        self.assertEqual(result["work_resolution"], "unresolved")
        self.assertEqual(result["discussion_type"], "general")
        # 제목 소비 신호로 먼저 HOLD를 보존했어도 검증기 오류는 별도로 남는다.
        self.assertIn("unresolved_worklike_hold:title_led_consumption", result["consistency_flags"])
        self.assertIn("verifier_technical_failure", result["consistency_flags"])
        self.assertIsNone(result["official_title"])

