    def test_sanitize_reason_removes_stale_non_relevant_consistency_line_for_relevant_result(self):
        reason = (
            "[판정 요약] - 판정: 관련(정식 제목 미확정) - discussion_type: general - 공식 제목: 미확정\n\n"
            "[정합성 교정]\n"
            "- 최종 판정은 비관련 포스트(discussion_type=noise)이며 원문 reason의 작품 확정 결론을 완화함.\n"
        )

        sanitized = AgenticPipeline._sanitize_reason(
            reason,
            is_relevant=True,
            discussion_type="general",
            official_title=None,
        )

        self.assertNotIn("최종 판정은 비관련 포스트", sanitized)
        self.assertIn("최종 판정은 관련 포스트(discussion_type=general, 공식 제목은 미확정)", sanitized)

    def test_sanitize_reason_neutralizes_unresolved_relevant_template_for_non_relevant_result(self):
        reason = (
            "[판정 요약]\n"
            "- 판정: 비관련\n"
            "- discussion_type: noise\n"
            "- 공식 제목: 미확정\n"
            "- 핵심 결론: 작품 관련 단서는 충분하지만 단일 공식 제목을 확정할 증거가 부족하여 제목 지목을 보류했습니다.\n"
            "- Verifier: 작품 토론으로 단정하기 어려움하기에는 증거가 부족함.\n"
            "[최종 종합]\n"
            "- 관련 포스트로 판정하되, 원문 앵커와 검색 증거를 종합했을 때 단일 공식 제목 확정은 위험하여 미확정으로 유지합니다.\n"
            "[정합성 교정]\n"
            "- 최종 판정은 관련 포스트(discussion_type=review, 공식 제목은 미확정)이며 원문 reason의 false 표기를 교정함.\n"
            "[근거 스코어]\n"
            "- title_resolution: -2 (관련 판정이지만 정식 제목 미확정)\n"
            "- decision_alignment: +1 (is_relevant=false, dt=review)\n"
            "[코드가드 unresolved_worklike_preserve: LLM(False)→최종(True)]"
        )

        sanitized = AgenticPipeline._sanitize_reason(
            reason,
            is_relevant=False,
            discussion_type="noise",
            official_title=None,
        )

        self.assertNotIn("작품 관련 단서는 충분하지만", sanitized)
        self.assertNotIn("관련 포스트로 판정하되", sanitized)
        self.assertNotIn("단정하기 어려움하되", sanitized)
        self.assertNotIn("단정하기 어려움하기에는", sanitized)
        self.assertNotIn("관련 판정이지만 정식 제목 미확정", sanitized)
        self.assertNotIn("최종 판정은 관련 포스트", sanitized)
        self.assertNotIn("LLM(False)→최종(True)", sanitized)
        self.assertNotIn("dt=review", sanitized)
        self.assertIn("작품 고유 앵커가 부족해 관련 포스트로 단정하기 어렵고", sanitized)
        self.assertIn("관련 포스트로 단정하기 어려우며", sanitized)
        self.assertIn("작품 토론으로 단정하기에는 증거가 부족함", sanitized)
        self.assertIn("비관련 판정이며 정식 제목 미확정", sanitized)
        self.assertIn("후속 비관련 가드로 최종 승격하지 않음", sanitized)
        self.assertIn("decision_alignment: +1 (is_relevant=false)", sanitized)
        self.assertIn("최종 판정은 비관련 포스트(discussion_type=noise)", sanitized)

    def test_sanitize_reason_keeps_adjacent_trope_wording_without_non_relevant_post_note(self):
        reason = (
            "[판정 요약]\n"
            "- 판정: 주변 관련\n"
            "- discussion_type: trope_discussion\n"
            "- 공식 제목: 미확정\n"
            "- work_resolution: none\n"
            "- 핵심 결론: 특정 작품보다 장르/트로프 일반론이나 관습 토론에 가깝습니다.\n"
            "[최종 종합]\n"
            "- 주된 해석 축이 장르 일반론이어서 특정 작품 제목 확정은 하지 않습니다.\n"
            "[정합성 교정]\n"
            "- 최종 분류는 adjacent_relevant이며, 작품 주변 맥락은 인정하되 단일 공식 제목은 미확정으로 유지합니다."
        )

        sanitized = AgenticPipeline._sanitize_reason(
            reason,
            is_relevant=False,
            discussion_type="trope_discussion",
            official_title=None,
        )

        self.assertIn("- 판정: 주변 관련", sanitized)
        self.assertIn("최종 분류는 adjacent_relevant", sanitized)
        self.assertIn("특정 작품보다 장르/트로프 일반론", sanitized)
        self.assertNotIn("최종 판정은 비관련 포스트", sanitized)

    def test_unresolved_relevant_reason_avoids_stale_relevant_hygiene_phrase(self):
        pipeline = _build_pipeline()
        ctx = ConversationContext(
            post_id=11718094,
            post_data={
                "post_id": 11718094,
                "title": "집착보다 더 좋은 것은 의존",
                "content_blocks": [{"type": "text", "text": "난 너 없이 못 살아~~"}],
            },
            comments=["피폐 피폐 피폐"],
        )
        reason = pipeline._format_unresolved_relevant_reason(
            discussion_type="review",
            verifier_reason="검색 결과는 캐릭터명을 직접 지지하지 못함",
            arbiter_reason="title hold",
            grounding_issue="검색 결과가 본문 캐릭터와 직접 연결되지 않음",
            counter_arguments=[],
            ctx=ctx,
            verification_result={
                "grounding_check": {"anchor_found": "character_mention"},
                "novel_identity": {"evidence_type": "community_mention"},
                "inference": {"type": "work_discussion", "topic": "관계 묘사 평가"},
            },
            final_decision={"_title_deliberately_null": True},
        )

        self.assertIn("웹소설/장르 맥락은 보이나", reason)
        self.assertIn("단일 공식 제목 확정은 위험하여 미확정", reason)
        self.assertNotIn("작품 관련 단서는 충분하지만", reason)
        self.assertNotIn("관련 포스트로 판정하되", reason)

