    def test_vlm_fetch_filters_non_image_and_total_budget(self):
        class _Resp:
            def __init__(self, body: bytes, content_type: str) -> None:
                self.content = body
                self.headers = {"content-type": content_type}

            def raise_for_status(self) -> None:
                return None

        fake_llm = FakeMultimodalLLM()
        with patch.dict(
            "os.environ",
            {
                "LLM_VLM": "1",
                "LLM_OCR": "1",
                "LLM_VLM_MAX_IMAGE_BYTES": "32",
                "LLM_VLM_MAX_TOTAL_BYTES": "10",
                "LLM_VLM_CHUNK_MAX_IMAGES": "8",
                "LLM_VLM_CHUNK_MAX_BYTES": "32",
            },
            clear=False,
        ):
            pipeline = AgenticPipeline(llm=fake_llm, mcp=DummyMCP(), max_iterations=2)
            post = PostInput(
                post_id=403,
                title="이미지 셋",
                url="https://gall.dcinside.com/mgallery/board/view/?id=genrenovel&no=403",
                content_blocks=[
                    ContentBlock(type="image", url="https://dcimg1.dcinside.com/1.png"),
                    ContentBlock(type="image", url="https://dcimg1.dcinside.com/2.png"),
                ],
                comments=[],
            )
            post_dict = pipeline._post_to_dict(post)
            with patch(
                "llm_batch.agentic_pipeline.httpx.get",
                side_effect=[_Resp(b"12345678", "image/png"), _Resp(b"<html></html>", "text/html")],
            ):
                enriched = pipeline._maybe_enrich_post_images(post_dict=post_dict, comments=[])

            self.assertEqual(enriched["image_fetch_count"], 2)
            self.assertEqual(enriched["image_fetch_success"], 1)
            self.assertTrue(any("non_image_content_type" in x for x in enriched["image_enrichment_limitations"]))
            self.assertEqual(enriched["vlm_chunks_sent"], 1)

    def test_vlm_fetch_accepts_octet_stream_when_signature_is_image(self):
        class _Resp:
            def __init__(self, body: bytes, content_type: str) -> None:
                self.content = body
                self.headers = {"content-type": content_type}

            def raise_for_status(self) -> None:
                return None

        fake_llm = FakeMultimodalLLM()
        with patch.dict(
            "os.environ",
            {
                "LLM_VLM": "1",
                "LLM_OCR": "1",
                "LLM_VLM_MAX_IMAGE_BYTES": "1048576",
                "LLM_VLM_MAX_TOTAL_BYTES": "1048576",
            },
            clear=False,
        ):
            pipeline = AgenticPipeline(llm=fake_llm, mcp=DummyMCP(), max_iterations=2)
            post = PostInput(
                post_id=404,
                title="dcimg webp 테스트",
                url="https://gall.dcinside.com/mgallery/board/view/?id=genrenovel&no=404",
                content_blocks=[ContentBlock(type="image", url="https://dcimg7.dcinside.co.kr/example.webp")],
                comments=[],
            )
            post_dict = pipeline._post_to_dict(post)
            webp_bytes = b"RIFF" + (100).to_bytes(4, "little") + b"WEBPVP8 " + b"x" * 16
            with patch(
                "llm_batch.agentic_pipeline.httpx.get",
                return_value=_Resp(webp_bytes, "application/octet-stream"),
            ):
                enriched = pipeline._maybe_enrich_post_images(post_dict=post_dict, comments=[])

            self.assertEqual(enriched["image_fetch_success"], 1)
            self.assertTrue(enriched["vlm_enrichment_used"])
            self.assertEqual(enriched["image_enrichment"][0]["source_url"], "https://dcimg7.dcinside.co.kr/example.webp")

    def test_vlm_detects_progressive_jpeg_dimensions(self):
        progressive_jpeg = (
            b"\xff\xd8"
            b"\xff\xc2\x00\x11\x08\x00\x01\x01\x85\x03"
            b"\x01\x11\x00\x02\x11\x00\x03\x11\x00"
            b"\xff\xd9"
        )

        self.assertEqual(
            AgenticPipeline._detect_image_dimensions_from_bytes(progressive_jpeg, "image/jpeg"),
            (389, 1),
        )

    def test_vlm_fetch_skips_degenerate_image_geometry_without_vlm_call(self):
        class _Resp:
            def __init__(self, body: bytes, content_type: str) -> None:
                self.content = body
                self.headers = {"content-type": content_type}

            def raise_for_status(self) -> None:
                return None

        fake_llm = FakeMultimodalLLM()
        degenerate_jpeg = (
            b"\xff\xd8"
            b"\xff\xc2\x00\x11\x08\x00\x01\x01\x85\x03"
            b"\x01\x11\x00\x02\x11\x00\x03\x11\x00"
            b"\xff\xd9"
        )
        with patch.dict(
            "os.environ",
            {
                "LLM_VLM": "1",
                "LLM_OCR": "1",
                "LLM_VLM_MAX_IMAGE_BYTES": "1048576",
                "LLM_VLM_MAX_TOTAL_BYTES": "1048576",
                "LLM_VLM_MIN_IMAGE_WIDTH": "8",
                "LLM_VLM_MIN_IMAGE_HEIGHT": "8",
                "LLM_VLM_MAX_ASPECT_RATIO": "64",
            },
            clear=False,
        ):
            pipeline = AgenticPipeline(llm=fake_llm, mcp=DummyMCP(), max_iterations=2)
            post = PostInput(
                post_id=406,
                title="퇴행 이미지 방어 테스트",
                url="https://gall.dcinside.com/mgallery/board/view/?id=genrenovel&no=406",
                content_blocks=[ContentBlock(type="image", url="https://dcimg7.dcinside.co.kr/degenerate.jpg")],
                comments=[],
            )
            post_dict = pipeline._post_to_dict(post)
            with patch(
                "llm_batch.agentic_pipeline.httpx.get",
                return_value=_Resp(degenerate_jpeg, "application/octet-stream"),
            ) as mocked_get:
                enriched = pipeline._maybe_enrich_post_images(post_dict=post_dict, comments=[])

            self.assertEqual(enriched["image_fetch_count"], 1)
            self.assertEqual(enriched["image_fetch_success"], 0)
            self.assertFalse(enriched["vlm_enrichment_used"])
            self.assertEqual(fake_llm.calls, [])
            self.assertEqual(mocked_get.call_count, 1)
            self.assertTrue(
                any("image_geometry_too_small:389x1" in x for x in enriched["image_enrichment_limitations"])
            )

